-- ====================================================================================================
-- GestiaHR · Modelo de datos completo (fases 0 a 9)
-- PostgreSQL 17 (carga también en PostgreSQL 16). Cargar en una base vacía con un rol propietario:
--   psql -v ON_ERROR_STOP=1 -d gestiahr -f schema.sql
--
-- Convenciones
--   · Tablas y columnas en inglés, snake_case, tablas en plural. Comentarios en español.
--   · Multiempresa en esquema compartido: toda tabla de organización lleva tenant_id NOT NULL,
--     UNIQUE (tenant_id, id), RLS activado y forzado, y claves foráneas compuestas
--     (tenant_id, x_id) → (tenant_id, id): una fila no puede referenciar a otra organización.
--   · La aplicación fija la organización por transacción:  SET LOCAL app.tenant_id = '<uuid>';
--     Sin ese valor, las políticas no devuelven ninguna fila (no lanzan error).
--   · Tablas de plataforma (planes, organizaciones, catálogos globales) sin tenant_id ni RLS.
--   · Enumerados como text + CHECK; PK uuid v7 (uuid_v7(), ordenable por tiempo, decisión A-03); fechas con timestamptz;
--     montos numeric(14,2) con columna de moneda (char(3), ISO 4217).
--   · Historia con vigencia: valid_from / valid_to (ambas inclusive; valid_to NULL = vigente) y
--     restricción de exclusión que impide solapamientos (btree_gist).
--   · «-- SENSIBLE» marca columnas que exigen permiso por campo y registro de acceso.
--     Las columnas *_enc se cifran en la aplicación; las *_hash son huellas para búsqueda exacta.
--   · lock_version: concurrencia optimista. La aplicación actualiza con
--     WHERE id = ? AND lock_version = ?; el trigger incrementa el valor.
--   · deleted_at: borrado lógico (papelera). Los índices únicos de esas tablas son parciales.
--   · Tablas de registro de gran volumen (auditoría, accesos, actividad, intentos de ingreso, uso de API,
--     auditoría de plataforma) particionadas por mes sobre occurred_at (decisión A-06). Su PK es
--     (id, occurred_at). ensure_monthly_partitions() crea los meses siguientes; la retención descarta
--     particiones completas. Cada tabla tiene además una partición DEFAULT que no debe recibir filas.
--   · Las colas, la caché y los logs técnicos no viven en esta base (Redis / Horizon / agregador de logs).
-- ====================================================================================================

SET client_min_messages = warning;
SET check_function_bodies = on;

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ----------------------------------------------------------------------------------------------------
-- Roles de base de datos
--   gestia_app       rol de la aplicación de las organizaciones. Sin BYPASSRLS: siempre sujeto a RLS.
--   gestia_platform  rol de la consola SaaS y de las tareas de plataforma. Opera entre organizaciones.
-- Son roles sin inicio de sesión: los usuarios de conexión reales se crean aparte y heredan de ellos.
-- ----------------------------------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gestia_app') THEN
    CREATE ROLE gestia_app NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gestia_platform') THEN
    CREATE ROLE gestia_platform NOLOGIN NOSUPERUSER BYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
END
$$;

-- ----------------------------------------------------------------------------------------------------
-- Funciones de apoyo
-- ----------------------------------------------------------------------------------------------------

-- Organización activa de la sesión; NULL si no se fijó.
CREATE FUNCTION app_tenant_id() RETURNS uuid
LANGUAGE sql STABLE
AS $$ SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid $$;
COMMENT ON FUNCTION app_tenant_id() IS 'Organización activa de la sesión (app.tenant_id); NULL si no se fijó.';

-- UUID versión 7 (RFC 9562): 48 bits de milisegundos Unix + bits aleatorios. Ordenable por tiempo,
-- mantiene localidad en los índices y no expone volumen. La aplicación puede generarlo también
-- (Laravel 12 HasUuids genera v7); este DEFAULT cubre las inserciones hechas desde SQL.
-- En PostgreSQL 18 puede reemplazarse por la función nativa uuidv7().
CREATE FUNCTION uuid_v7() RETURNS uuid
LANGUAGE sql VOLATILE PARALLEL SAFE
AS $$
  SELECT encode(
    set_bit(set_bit(
      overlay(uuid_send(gen_random_uuid())
              placing substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
              FROM 1 FOR 6),
      52, 1), 53, 1),
    'hex')::uuid
$$;
COMMENT ON FUNCTION uuid_v7() IS 'UUID versión 7 ordenable por tiempo (decisión A-03). DEFAULT de todas las claves primarias.';

CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END
$$;

CREATE FUNCTION set_updated_at_and_lock() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := now();
  NEW.lock_version := OLD.lock_version + 1;
  RETURN NEW;
END
$$;

CREATE FUNCTION bump_lock_version() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.lock_version := OLD.lock_version + 1;
  RETURN NEW;
END
$$;

-- Tablas de solo inserción: cualquier UPDATE, DELETE o TRUNCATE falla (SQLSTATE AY001).
CREATE FUNCTION reject_mutation() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'La tabla % es de solo inserción: % no está permitido. Una corrección se registra como una fila nueva.', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'AY001';
END
$$;
COMMENT ON FUNCTION reject_mutation() IS 'Rechaza UPDATE, DELETE y TRUNCATE en tablas inalterables (auditoría, marcaciones, firmas, bitácora de IA, libros de saldos).';

-- ----------------------------------------------------------------------------------------------------
-- Particiones mensuales (decisión A-06)
-- Crea las particiones de p_months meses a partir del mes de p_from (UTC). Es idempotente.
-- Cada partición nueva hereda la política de aislamiento y no recibe privilegios propios: solo se accede
-- a ella a través de la tabla madre, donde rigen RLS y los privilegios. La consola de plataforma la
-- programa (por ejemplo, el día 1 de cada mes con 3 meses por delante). Para retener: DETACH + DROP
-- de las particiones vencidas, nunca DELETE.
-- ----------------------------------------------------------------------------------------------------
CREATE FUNCTION ensure_monthly_partitions(p_table regclass, p_from date, p_months integer DEFAULT 3) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp
AS $$
DECLARE
  v_start date := date_trunc('month', p_from)::date;
  v_name text;
  v_created integer := 0;
  v_has_tenant boolean;
  v_parent text := (SELECT relname FROM pg_class WHERE oid = p_table);
BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = p_table) <> 'p' THEN
    RAISE EXCEPTION '% no es una tabla particionada', p_table;
  END IF;
  v_has_tenant := EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = p_table AND attname = 'tenant_id' AND NOT attisdropped);
  FOR i IN 0 .. p_months - 1 LOOP
    v_name := v_parent || '_p' || to_char(v_start + make_interval(months => i), 'YYYYMM');
    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = v_name AND relnamespace = 'public'::regnamespace) THEN
      EXECUTE format('CREATE TABLE %I PARTITION OF %s FOR VALUES FROM (%L) TO (%L)', v_name, p_table,
                     ((v_start + make_interval(months => i))::timestamp AT TIME ZONE 'UTC'),
                     ((v_start + make_interval(months => i + 1))::timestamp AT TIME ZONE 'UTC'));
      IF v_has_tenant THEN
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', v_name);
        EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', v_name);
        EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = app_tenant_id()) WITH CHECK (tenant_id = app_tenant_id())', v_name);
      END IF;
      EXECUTE format('REVOKE ALL ON %I FROM PUBLIC, gestia_app, gestia_platform', v_name);
      v_created := v_created + 1;
    END IF;
  END LOOP;
  RETURN v_created;
END
$$;
COMMENT ON FUNCTION ensure_monthly_partitions(regclass, date, integer) IS 'Crea particiones mensuales (UTC) de una tabla de registro particionada, con RLS y sin privilegios directos. Idempotente.';


-- ==================================================================================================
-- FASE 0 · CIMIENTOS
-- ==================================================================================================

-- --------------------------------------------------------------------------------------------------
-- TEN · Multiempresa y aislamiento
-- --------------------------------------------------------------------------------------------------

CREATE TABLE countries (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  code text NOT NULL CHECK (char_length(code) = 2),
  name text NOT NULL,
  default_currency char(3),
  default_locale text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_countries_code UNIQUE (code)
);
COMMENT ON TABLE countries IS 'Catálogo de países (ISO 3166-1 alfa-2) que usan los paquetes de país y las razones sociales.';
CREATE TRIGGER trg_countries_touch BEFORE UPDATE ON countries FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE currencies (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  code char(3) NOT NULL,
  name text NOT NULL,
  symbol text,
  decimals smallint NOT NULL DEFAULT 2,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_currencies_code UNIQUE (code)
);
COMMENT ON TABLE currencies IS 'Catálogo de monedas (ISO 4217) admitidas en montos y compensaciones.';
CREATE TRIGGER trg_currencies_touch BEFORE UPDATE ON currencies FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE tenants (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  slug text NOT NULL,
  name text NOT NULL,
  status text NOT NULL DEFAULT 'trial' CHECK (status IN ('trial','active','suspended','blocked','cancelled','grace_period','deleted')),
  country_code text NOT NULL,
  default_currency char(3) NOT NULL,
  default_locale text NOT NULL DEFAULT 'es',
  timezone text NOT NULL DEFAULT 'America/Lima',
  is_demo boolean NOT NULL DEFAULT false,
  is_partner_managed boolean NOT NULL DEFAULT false,
  trial_ends_at timestamptz,
  suspended_at timestamptz,
  suspension_reason text,
  storage_region text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT fk_tenants_country_code FOREIGN KEY (country_code) REFERENCES countries (code)
);
COMMENT ON TABLE tenants IS 'Organización cliente (tenant). Raíz del aislamiento: toda tabla de organización referencia su id.';
CREATE UNIQUE INDEX uq_tenants_slug ON tenants (slug) WHERE deleted_at IS NULL;
CREATE INDEX ix_tenants_country_code ON tenants (country_code);
CREATE TRIGGER trg_tenants_touch BEFORE UPDATE ON tenants FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE tenant_domains (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL,
  domain text NOT NULL,
  kind text NOT NULL DEFAULT 'subdomain' CHECK (kind IN ('subdomain','custom')),
  verified_at timestamptz,
  is_primary boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_tenant_domains_domain UNIQUE (domain),
  CONSTRAINT fk_tenant_domains_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);
COMMENT ON TABLE tenant_domains IS 'Dominios y subdominios por los que se resuelve la organización (incluye dominio propio de marca blanca).';
CREATE INDEX ix_tenant_domains_tenant_id ON tenant_domains (tenant_id);
CREATE TRIGGER trg_tenant_domains_touch BEFORE UPDATE ON tenant_domains FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE tenant_status_events (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL,
  from_status text,
  to_status text NOT NULL,
  reason text,
  platform_user_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT fk_tenant_status_events_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);
COMMENT ON TABLE tenant_status_events IS 'Historial inalterable de cambios de estado de la organización (pruebas, suspensiones, bloqueos, reactivaciones).';
CREATE INDEX ix_tenant_status_events_tenant_id ON tenant_status_events (tenant_id);
CREATE INDEX ix_tenant_status_events_platform_user_id ON tenant_status_events (platform_user_id);
CREATE TRIGGER trg_tenant_status_events_inmutable BEFORE UPDATE OR DELETE ON tenant_status_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_tenant_status_events_no_truncate BEFORE TRUNCATE ON tenant_status_events FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

-- --------------------------------------------------------------------------------------------------
-- SAS · Consola SaaS: organizaciones, planes, módulos, límites, feature flags, soporte y salud
-- --------------------------------------------------------------------------------------------------

CREATE TABLE modules (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  code text NOT NULL,
  name text NOT NULL,
  phase smallint NOT NULL,
  is_core boolean NOT NULL DEFAULT false,
  epic_codes text[] NOT NULL,
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_modules_code UNIQUE (code)
);
COMMENT ON TABLE modules IS 'Módulos comerciales que una organización puede contratar; agrupan épicas del backlog.';
CREATE TRIGGER trg_modules_touch BEFORE UPDATE ON modules FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE module_dependencies (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  module_code text NOT NULL,
  depends_on_code text NOT NULL,
  is_required boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_module_dependencies_module_code_depends_on_code UNIQUE (module_code, depends_on_code),
  CONSTRAINT fk_module_dependencies_module_code FOREIGN KEY (module_code) REFERENCES modules (code),
  CONSTRAINT fk_module_dependencies_depends_on_code FOREIGN KEY (depends_on_code) REFERENCES modules (code)
);
COMMENT ON TABLE module_dependencies IS 'Dependencias entre módulos comerciales (un módulo no se activa sin sus requisitos).';
CREATE INDEX ix_module_dependencies_depends_on_code ON module_dependencies (depends_on_code);
CREATE TRIGGER trg_module_dependencies_touch BEFORE UPDATE ON module_dependencies FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE plans (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  code text NOT NULL,
  name text NOT NULL,
  description text,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','inactive')),
  billing_cycle text NOT NULL DEFAULT 'monthly' CHECK (billing_cycle IN ('monthly','annual')),
  price numeric(14,2),
  currency char(3),
  trial_days integer,
  is_public boolean NOT NULL DEFAULT true,
  duplicated_from_plan_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT fk_plans_duplicated_from_plan_id FOREIGN KEY (duplicated_from_plan_id) REFERENCES plans (id)
);
COMMENT ON TABLE plans IS 'Planes comerciales definidos por el superadministrador (nombres libres, duplicables).';
CREATE UNIQUE INDEX uq_plans_code ON plans (code) WHERE deleted_at IS NULL;
CREATE INDEX ix_plans_duplicated_from_plan_id ON plans (duplicated_from_plan_id);
CREATE TRIGGER trg_plans_touch BEFORE UPDATE ON plans FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE plan_modules (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  plan_id uuid NOT NULL,
  module_code text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_plan_modules_plan_id_module_code UNIQUE (plan_id, module_code),
  CONSTRAINT fk_plan_modules_plan_id FOREIGN KEY (plan_id) REFERENCES plans (id),
  CONSTRAINT fk_plan_modules_module_code FOREIGN KEY (module_code) REFERENCES modules (code)
);
COMMENT ON TABLE plan_modules IS 'Módulos incluidos en cada plan.';
CREATE INDEX ix_plan_modules_module_code ON plan_modules (module_code);
CREATE TRIGGER trg_plan_modules_touch BEFORE UPDATE ON plan_modules FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE plan_limits (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  plan_id uuid NOT NULL,
  limit_code text NOT NULL,
  limit_value numeric(14,2),
  is_unlimited boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_plan_limits_plan_id_limit_code UNIQUE (plan_id, limit_code),
  CONSTRAINT fk_plan_limits_plan_id FOREIGN KEY (plan_id) REFERENCES plans (id)
);
COMMENT ON TABLE plan_limits IS 'Límites por plan (colaboradores, administradores, almacenamiento, razones sociales, llamadas de API).';
CREATE TRIGGER trg_plan_limits_touch BEFORE UPDATE ON plan_limits FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE plan_features (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  plan_id uuid NOT NULL,
  feature_code text NOT NULL,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_plan_features_plan_id_feature_code UNIQUE (plan_id, feature_code),
  CONSTRAINT fk_plan_features_plan_id FOREIGN KEY (plan_id) REFERENCES plans (id)
);
COMMENT ON TABLE plan_features IS 'Funcionalidades puntuales habilitadas por plan.';
CREATE TRIGGER trg_plan_features_touch BEFORE UPDATE ON plan_features FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE addons (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  code text NOT NULL,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('module','limit','feature','service')),
  web_product_code text,
  limit_code text,
  limit_increment numeric(14,2),
  price numeric(14,2),
  currency char(3),
  billing_cycle text NOT NULL DEFAULT 'monthly' CHECK (billing_cycle IN ('monthly','annual','one_time')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
COMMENT ON TABLE addons IS 'Complementos contratables sobre un plan (módulo extra, ampliación de límite, funcionalidad o servicio).';
CREATE UNIQUE INDEX uq_addons_code ON addons (code) WHERE deleted_at IS NULL;
CREATE TRIGGER trg_addons_touch BEFORE UPDATE ON addons FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE addon_modules (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  addon_id uuid NOT NULL,
  module_code text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_addon_modules_addon_id_module_code UNIQUE (addon_id, module_code),
  CONSTRAINT fk_addon_modules_addon_id FOREIGN KEY (addon_id) REFERENCES addons (id),
  CONSTRAINT fk_addon_modules_module_code FOREIGN KEY (module_code) REFERENCES modules (code)
);
COMMENT ON TABLE addon_modules IS 'Módulos que habilita un complemento de tipo módulo (un producto de la web puede habilitar varios, docs/01 §4.2).';
CREATE INDEX ix_addon_modules_module_code ON addon_modules (module_code);
CREATE TRIGGER trg_addon_modules_touch BEFORE UPDATE ON addon_modules FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE subscriptions (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL,
  plan_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'trialing' CHECK (status IN ('trialing','active','past_due','suspended','cancelled','expired')),
  billing_cycle text NOT NULL DEFAULT 'monthly' CHECK (billing_cycle IN ('monthly','annual')),
  price numeric(14,2),
  currency char(3),
  starts_on date NOT NULL,
  ends_on date,
  trial_ends_on date,
  cancelled_at timestamptz,
  cancel_reason text,
  license_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT fk_subscriptions_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id),
  CONSTRAINT fk_subscriptions_plan_id FOREIGN KEY (plan_id) REFERENCES plans (id)
);
COMMENT ON TABLE subscriptions IS 'Suscripción de una organización a un plan, con su ciclo, estado y periodo de prueba.';
CREATE INDEX ix_subscriptions_tenant_id ON subscriptions (tenant_id);
CREATE INDEX ix_subscriptions_plan_id ON subscriptions (plan_id);
CREATE TRIGGER trg_subscriptions_touch BEFORE UPDATE ON subscriptions FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE subscription_addons (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  subscription_id uuid NOT NULL,
  addon_id uuid NOT NULL,
  quantity integer NOT NULL DEFAULT 1,
  price numeric(14,2),
  currency char(3),
  starts_on date NOT NULL,
  ends_on date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT fk_subscription_addons_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscriptions (id),
  CONSTRAINT fk_subscription_addons_addon_id FOREIGN KEY (addon_id) REFERENCES addons (id)
);
COMMENT ON TABLE subscription_addons IS 'Complementos contratados dentro de una suscripción.';
CREATE INDEX ix_subscription_addons_subscription_id ON subscription_addons (subscription_id);
CREATE INDEX ix_subscription_addons_addon_id ON subscription_addons (addon_id);
CREATE TRIGGER trg_subscription_addons_touch BEFORE UPDATE ON subscription_addons FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE saas_invoices (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL,
  subscription_id uuid,
  number text NOT NULL,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','issued','paid','overdue','void')),
  period_start date NOT NULL,
  period_end date NOT NULL,
  subtotal numeric(14,2) NOT NULL,
  tax numeric(14,2) NOT NULL DEFAULT 0,
  total numeric(14,2) NOT NULL,
  currency char(3) NOT NULL,
  issued_at timestamptz,
  due_on date,
  paid_at timestamptz,
  external_ref text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_saas_invoices_number UNIQUE (number),
  CONSTRAINT fk_saas_invoices_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id),
  CONSTRAINT fk_saas_invoices_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscriptions (id)
);
COMMENT ON TABLE saas_invoices IS 'Facturación del SaaS a la organización cliente (no es la nómina del cliente).';
CREATE INDEX ix_saas_invoices_tenant_id ON saas_invoices (tenant_id);
CREATE INDEX ix_saas_invoices_subscription_id ON saas_invoices (subscription_id);
CREATE TRIGGER trg_saas_invoices_touch BEFORE UPDATE ON saas_invoices FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE saas_invoice_lines (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  saas_invoice_id uuid NOT NULL,
  description text NOT NULL,
  quantity numeric(14,2) NOT NULL DEFAULT 1,
  unit_price numeric(14,2) NOT NULL,
  amount numeric(14,2) NOT NULL,
  currency char(3) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT fk_saas_invoice_lines_saas_invoice_id FOREIGN KEY (saas_invoice_id) REFERENCES saas_invoices (id)
);
COMMENT ON TABLE saas_invoice_lines IS 'Líneas de la factura SaaS.';
CREATE INDEX ix_saas_invoice_lines_saas_invoice_id ON saas_invoice_lines (saas_invoice_id);
CREATE TRIGGER trg_saas_invoice_lines_touch BEFORE UPDATE ON saas_invoice_lines FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE tenant_modules (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  module_code text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive','trial')),
  source text NOT NULL DEFAULT 'plan' CHECK (source IN ('plan','addon','manual','trial')),
  activated_at timestamptz,
  deactivated_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
