CREATE TABLE platform_users (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  email text NOT NULL,
  full_name text NOT NULL,
  password_hash text,  -- SENSIBLE
  role text NOT NULL DEFAULT 'support' CHECK (role IN ('superadmin','support','billing','readonly')),
  mfa_secret_enc text,  -- SENSIBLE (cifrado en la aplicación)
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','blocked')),
  last_login_at timestamptz,
  mfa_confirmed_at timestamptz,
  mfa_last_used_step bigint,
  failed_attempts integer NOT NULL DEFAULT 0,
  locked_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1
);
COMMENT ON TABLE platform_users IS 'Usuarios de la consola del propietario del SaaS, separados por completo de los usuarios de las organizaciones.';
CREATE UNIQUE INDEX uq_platform_users_email ON platform_users (email) WHERE deleted_at IS NULL;
CREATE TRIGGER trg_platform_users_touch BEFORE UPDATE ON platform_users FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE platform_sessions (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  platform_user_id uuid NOT NULL,
  session_hash text NOT NULL,  -- SENSIBLE
  ip inet,
  user_agent text,
  mfa_passed boolean NOT NULL DEFAULT false,
  last_seen_at timestamptz,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_platform_sessions_session_hash UNIQUE (session_hash),
  CONSTRAINT fk_platform_sessions_platform_user_id FOREIGN KEY (platform_user_id) REFERENCES platform_users (id)
);
COMMENT ON TABLE platform_sessions IS 'Sesiones de la consola SaaS (SAS-1): cookie propia, segundo factor siempre obligatorio, revocables.';
CREATE INDEX ix_platform_sessions_platform_user_id ON platform_sessions (platform_user_id);
CREATE TRIGGER trg_platform_sessions_touch BEFORE UPDATE ON platform_sessions FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE platform_audit_events (
  id uuid NOT NULL DEFAULT uuid_v7(),
  platform_user_id uuid,
  tenant_id uuid,
  action text NOT NULL,
  entity_type text,
  entity_id uuid,
  before_data jsonb,
  after_data jsonb,
  ip inet,
  user_agent text,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pk_platform_audit_events PRIMARY KEY (id, occurred_at),
  CONSTRAINT fk_platform_audit_events_platform_user_id FOREIGN KEY (platform_user_id) REFERENCES platform_users (id),
  CONSTRAINT fk_platform_audit_events_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id)
) PARTITION BY RANGE (occurred_at);
COMMENT ON TABLE platform_audit_events IS 'Auditoría inalterable de la consola SaaS (quién, qué, sobre qué organización, antes y después).';
CREATE INDEX ix_platform_audit_events_platform_user_id ON platform_audit_events (platform_user_id);
CREATE INDEX ix_platform_audit_events_tenant_id ON platform_audit_events (tenant_id);
CREATE TABLE platform_audit_events_default PARTITION OF platform_audit_events DEFAULT;
COMMENT ON TABLE platform_audit_events_default IS 'Partición de respaldo de platform_audit_events: no debería recibir filas; si las recibe, falta crear el mes con ensure_monthly_partitions().';
CREATE TRIGGER trg_platform_audit_events_inmutable BEFORE UPDATE OR DELETE ON platform_audit_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_platform_audit_events_no_truncate BEFORE TRUNCATE ON platform_audit_events FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

