);
COMMENT ON TABLE web_products IS 'Productos de la web (Personas, Tiempo, Planilla, Talento, Formación y Suite) según docs/01 §4.1; agrupan módulos comerciales.';
CREATE TRIGGER trg_web_products_touch BEFORE UPDATE ON web_products FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE web_product_modules (
