  CONSTRAINT fk_web_product_modules_web_product_id FOREIGN KEY (web_product_id) REFERENCES web_products (id),
  CONSTRAINT fk_web_product_modules_module_code FOREIGN KEY (module_code) REFERENCES modules (code)
