CREATE INDEX ix_web_product_modules_module_code ON web_product_modules (module_code);
CREATE TRIGGER trg_web_product_modules_touch BEFORE UPDATE ON web_product_modules FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE web_leads (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
