  CONSTRAINT fk_web_leads_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);
COMMENT ON TABLE web_leads IS 'Leads del sitio: demo, contacto, partner, boletín, calculadora, lista de espera o registro abandonado.';
CREATE INDEX ix_web_leads_web_product_id ON web_leads (web_product_id);
