CREATE TABLE audit_events (
  id uuid NOT NULL DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  actor_user_id uuid,
  actor_kind text NOT NULL DEFAULT 'user' CHECK (actor_kind IN ('user','api_token','system','platform_support','ai_assistant')),
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id uuid,
  before_data jsonb,  -- SENSIBLE
  after_data jsonb,  -- SENSIBLE
  changed_fields text[],
  reason text,
  ip inet,
  user_agent text,
  request_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  chain_seq bigint,
  prev_hash text,
  row_hash text,
  created_at timestamptz NOT NULL DEFAULT now(),
