CREATE TABLE employments (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  person_id uuid NOT NULL,
  legal_entity_id uuid NOT NULL,
  employee_code text NOT NULL,
  kind text NOT NULL DEFAULT 'employee' CHECK (kind IN ('employee','intern','apprentice')),
  worker_category text NOT NULL DEFAULT 'employee' CHECK (worker_category IN ('executive','employee','worker')),
  hire_date date NOT NULL,
  seniority_date date,
  termination_date date,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended','terminated','terminating','cancelled')),
  rehire_of_employment_id uuid,
  source_application_id uuid,
  probation_ends_on date,
  created_at timestamptz NOT NULL DEFAULT now(),
