  tenant_id uuid NOT NULL REFERENCES tenants (id),
  signature_request_id uuid NOT NULL,
  user_id uuid,
  person_id uuid,
  signer_name text NOT NULL,
  signer_role text,
  sort_order integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','viewed','signed','declined')),
  viewed_at timestamptz,
  signed_at timestamptz,
  declined_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_signature_request_signers_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_signature_request_signers_signature_request_id FOREIGN KEY (tenant_id, signature_request_id) REFERENCES signature_requests (tenant_id, id),
  CONSTRAINT fk_signature_request_signers_user_id FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_signature_request_signers_person_id FOREIGN KEY (tenant_id, person_id) REFERENCES people (tenant_id, id)
);
COMMENT ON TABLE signature_request_signers IS 'Firmantes de una solicitud y su estado.';
CREATE INDEX ix_signature_request_signers_signature_request_id ON signature_request_signers (tenant_id, signature_request_id);
CREATE INDEX ix_signature_request_signers_user_id ON signature_request_signers (tenant_id, user_id);
CREATE INDEX ix_signature_request_signers_person_id ON signature_request_signers (tenant_id, person_id);
ALTER TABLE signature_request_signers ENABLE ROW LEVEL SECURITY;
ALTER TABLE signature_request_signers FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON signature_request_signers USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_signature_request_signers_touch BEFORE UPDATE ON signature_request_signers FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE signature_events (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  signature_request_id uuid NOT NULL,
  signer_id uuid,
  event text NOT NULL CHECK (event IN ('created','sent','viewed','otp_sent','otp_verified','signed','declined','completed','expired','cancelled')),
  document_hash text NOT NULL,
  hash_algorithm text NOT NULL DEFAULT 'SHA-256',
  ip inet,
  user_agent text,
  otp_channel text CHECK (otp_channel IN ('email','sms','whatsapp')),
  otp_reference_hash text,
  timestamp_token text,
  provider_evidence jsonb,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_signature_events_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_signature_events_signature_request_id FOREIGN KEY (tenant_id, signature_request_id) REFERENCES signature_requests (tenant_id, id),
  CONSTRAINT fk_signature_events_signer_id FOREIGN KEY (tenant_id, signer_id) REFERENCES signature_request_signers (tenant_id, id)
);
COMMENT ON TABLE signature_events IS 'Evidencia inalterable de firma (C-12): huella del documento, sello de tiempo, IP, verificación por OTP y evidencia del proveedor.';
CREATE INDEX ix_signature_events_signature_request_id ON signature_events (tenant_id, signature_request_id);
CREATE INDEX ix_signature_events_signer_id ON signature_events (tenant_id, signer_id);
ALTER TABLE signature_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE signature_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON signature_events USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_signature_events_inmutable BEFORE UPDATE OR DELETE ON signature_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_signature_events_no_truncate BEFORE TRUNCATE ON signature_events FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

