COMMENT ON TABLE import_jobs IS 'Importación masiva por etapas: subir, mapear, validar, previsualizar e importar (nunca directo).';
CREATE INDEX ix_import_jobs_import_template_id ON import_jobs (tenant_id, import_template_id);
CREATE INDEX ix_import_jobs_stored_file_id ON import_jobs (tenant_id, stored_file_id);
