-- --------------------------------------------------------------------------------------------------
-- AYU · Centro de ayuda
-- --------------------------------------------------------------------------------------------------
-- La ayuda del producto es de plataforma (la publica GestiaHR); los artículos de la organización son de cada organización y la mesa de ayuda (HSD) los reutiliza. La búsqueda usa índices GIN sobre `search_vector` (ver `epilogue.sql`).

CREATE TABLE help_articles (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  slug text NOT NULL,
  locale text NOT NULL DEFAULT 'es',
  title text NOT NULL,
  summary text,
  body text NOT NULL,
  kind text NOT NULL DEFAULT 'guide' CHECK (kind IN ('guide','screen','field','tour','release_note','faq')),
  module_code text,
  roles text[],
  screen_keys text[],
  product_version text NOT NULL,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')),
  published_at timestamptz,
  search_vector tsvector GENERATED ALWAYS AS (to_tsvector('spanish', coalesce(title, '') || ' ' || coalesce(body, ''))) STORED,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT fk_help_articles_module_code FOREIGN KEY (module_code) REFERENCES modules (code)
);
COMMENT ON TABLE help_articles IS 'Artículo de ayuda del producto que publica GestiaHR: módulo, roles, pantallas, idioma y versión del producto.';
CREATE UNIQUE INDEX uq_help_articles_slug_locale ON help_articles (slug, locale) WHERE deleted_at IS NULL;
CREATE INDEX ix_help_articles_module_code ON help_articles (module_code);
CREATE TRIGGER trg_help_articles_touch BEFORE UPDATE ON help_articles FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE help_article_versions (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  help_article_id uuid NOT NULL,
  version_number integer NOT NULL,
  product_version text NOT NULL,
  title text NOT NULL,
  body text NOT NULL,
  published_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_help_article_versions_help_article_id_version_number UNIQUE (help_article_id, version_number),
  CONSTRAINT fk_help_article_versions_help_article_id FOREIGN KEY (help_article_id) REFERENCES help_articles (id)
);
COMMENT ON TABLE help_article_versions IS 'Versión publicada de un artículo del producto; no se modifica.';
CREATE TRIGGER trg_help_article_versions_inmutable BEFORE UPDATE OR DELETE ON help_article_versions FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_help_article_versions_no_truncate BEFORE TRUNCATE ON help_article_versions FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

CREATE TABLE help_article_feedback (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  help_article_id uuid NOT NULL,
  user_id uuid,
  is_helpful boolean NOT NULL,
  comment text,
  screen_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_help_article_feedback_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_help_article_feedback_help_article_id FOREIGN KEY (help_article_id) REFERENCES help_articles (id),
  CONSTRAINT fk_help_article_feedback_user_id FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE help_article_feedback IS 'Valoración «¿te sirvió?» de un artículo del producto por un usuario de la organización.';
CREATE INDEX ix_help_article_feedback_help_article_id ON help_article_feedback (tenant_id, help_article_id);
CREATE INDEX ix_help_article_feedback_user_id ON help_article_feedback (tenant_id, user_id);
ALTER TABLE help_article_feedback ENABLE ROW LEVEL SECURITY;
ALTER TABLE help_article_feedback FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON help_article_feedback USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
