CREATE INDEX ix_kb_articles_kb_category_id ON kb_articles (tenant_id, kb_category_id);
CREATE INDEX ix_kb_articles_owner_user_id ON kb_articles (tenant_id, owner_user_id);
ALTER TABLE kb_articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE kb_articles FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON kb_articles USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
