CREATE TABLE attendance_devices (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  code text NOT NULL,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('biometric_clock','kiosk','tablet','mobile','qr_station','api')),
  site_id uuid,
  integration_id uuid,
  serial_number text,
  device_token_hash text,
  timezone text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive','lost')),
  last_sync_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_attendance_devices_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_attendance_devices_site_id FOREIGN KEY (tenant_id, site_id) REFERENCES sites (tenant_id, id)
);
COMMENT ON TABLE attendance_devices IS 'Dispositivos de marcación: reloj biométrico, kiosko, tableta, estación QR o conector por API (E-07).';
CREATE UNIQUE INDEX uq_attendance_devices_code ON attendance_devices (tenant_id, code) WHERE deleted_at IS NULL;
CREATE INDEX ix_attendance_devices_site_id ON attendance_devices (tenant_id, site_id);
CREATE INDEX ix_attendance_devices_integration_id ON attendance_devices (tenant_id, integration_id);
ALTER TABLE attendance_devices ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_devices FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance_devices USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_attendance_devices_touch BEFORE UPDATE ON attendance_devices FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE attendance_geofences (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  site_id uuid,
  name text NOT NULL,
  latitude numeric(9,6) NOT NULL,
  longitude numeric(9,6) NOT NULL,
  radius_m integer NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CONSTRAINT uq_attendance_geofences_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_attendance_geofences_site_id FOREIGN KEY (tenant_id, site_id) REFERENCES sites (tenant_id, id)
);
COMMENT ON TABLE attendance_geofences IS 'Geocercas válidas para marcar desde la app.';
CREATE INDEX ix_attendance_geofences_site_id ON attendance_geofences (tenant_id, site_id);
ALTER TABLE attendance_geofences ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_geofences FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance_geofences USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_attendance_geofences_touch BEFORE UPDATE ON attendance_geofences FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE attendance_sync_batches (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  attendance_device_id uuid,
  submitted_by_user_id uuid,
  client_batch_id text NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now(),
  record_count integer NOT NULL,
  accepted_count integer,
  rejected_count integer,
  status text NOT NULL DEFAULT 'received' CHECK (status IN ('received','processed','partial','failed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_attendance_sync_batches_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_attendance_sync_batches_client_batch_id UNIQUE (tenant_id, client_batch_id),
  CONSTRAINT fk_attendance_sync_batches_attendance_device_id FOREIGN KEY (tenant_id, attendance_device_id) REFERENCES attendance_devices (tenant_id, id),
  CONSTRAINT fk_attendance_sync_batches_submitted_by_user_id FOREIGN KEY (tenant_id, submitted_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE attendance_sync_batches IS 'Lotes sincronizados por dispositivos o app en modo sin conexión; evita duplicar marcaciones.';
CREATE INDEX ix_attendance_sync_batches_attendance_device_id ON attendance_sync_batches (tenant_id, attendance_device_id);
CREATE INDEX ix_attendance_sync_batches_submitted_by_user_id ON attendance_sync_batches (tenant_id, submitted_by_user_id);
ALTER TABLE attendance_sync_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_sync_batches FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance_sync_batches USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_attendance_sync_batches_touch BEFORE UPDATE ON attendance_sync_batches FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE attendance_punches (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  employment_id uuid NOT NULL,
  punched_at timestamptz NOT NULL,
  kind text NOT NULL CHECK (kind IN ('in','out','break_start','break_end')),
  method text NOT NULL CHECK (method IN ('web','app','qr','kiosk','pin','biometric','crew','api','import','manual')),
  attendance_device_id uuid,
  site_id uuid,
  latitude numeric(9,6),  -- SENSIBLE
  longitude numeric(9,6),  -- SENSIBLE
  accuracy_m numeric(8,2),
  geofence_id uuid,
  within_geofence boolean,
  selfie_file_id uuid,  -- SENSIBLE
  liveness_score numeric(5,4),
  registered_by_user_id uuid,
  is_offline boolean NOT NULL DEFAULT false,
  device_recorded_at timestamptz,
  sync_batch_id uuid,
  client_id text,
  source_hash text,
  entry_type text NOT NULL DEFAULT 'original' CHECK (entry_type IN ('original','correction','annulment')),
  corrects_punch_id uuid,
  correction_reason text,
  correction_request_id uuid,
  ip inet,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_attendance_punches_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT ck_attendance_punches_1 CHECK (entry_type = 'original' OR (corrects_punch_id IS NOT NULL AND correction_reason IS NOT NULL)),
  CONSTRAINT uq_attendance_punches_r1 UNIQUE (tenant_id, client_id),
  CONSTRAINT fk_attendance_punches_employment_id FOREIGN KEY (tenant_id, employment_id) REFERENCES employments (tenant_id, id),
  CONSTRAINT fk_attendance_punches_attendance_device_id FOREIGN KEY (tenant_id, attendance_device_id) REFERENCES attendance_devices (tenant_id, id),
  CONSTRAINT fk_attendance_punches_site_id FOREIGN KEY (tenant_id, site_id) REFERENCES sites (tenant_id, id),
  CONSTRAINT fk_attendance_punches_geofence_id FOREIGN KEY (tenant_id, geofence_id) REFERENCES attendance_geofences (tenant_id, id),
  CONSTRAINT fk_attendance_punches_selfie_file_id FOREIGN KEY (tenant_id, selfie_file_id) REFERENCES stored_files (tenant_id, id),
  CONSTRAINT fk_attendance_punches_registered_by_user_id FOREIGN KEY (tenant_id, registered_by_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_attendance_punches_sync_batch_id FOREIGN KEY (tenant_id, sync_batch_id) REFERENCES attendance_sync_batches (tenant_id, id),
  CONSTRAINT fk_attendance_punches_corrects_punch_id FOREIGN KEY (tenant_id, corrects_punch_id) REFERENCES attendance_punches (tenant_id, id)
);
COMMENT ON TABLE attendance_punches IS 'Marcación de asistencia inalterable (C-07, DS 004-2006-TR). Una corrección es una fila nueva que apunta a la original e indica el motivo. client_id deduplica las marcaciones sin conexión.';
CREATE INDEX ix_attendance_punches_attendance_device_id ON attendance_punches (tenant_id, attendance_device_id);
CREATE INDEX ix_attendance_punches_site_id ON attendance_punches (tenant_id, site_id);
CREATE INDEX ix_attendance_punches_geofence_id ON attendance_punches (tenant_id, geofence_id);
CREATE INDEX ix_attendance_punches_selfie_file_id ON attendance_punches (tenant_id, selfie_file_id);
CREATE INDEX ix_attendance_punches_registered_by_user_id ON attendance_punches (tenant_id, registered_by_user_id);
CREATE INDEX ix_attendance_punches_sync_batch_id ON attendance_punches (tenant_id, sync_batch_id);
CREATE INDEX ix_attendance_punches_corrects_punch_id ON attendance_punches (tenant_id, corrects_punch_id);
CREATE INDEX ix_attendance_punches_correction_request_id ON attendance_punches (tenant_id, correction_request_id);
CREATE INDEX ix_attendance_punches_employment_id_punched_at ON attendance_punches (tenant_id, employment_id, punched_at);
ALTER TABLE attendance_punches ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_punches FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance_punches USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_attendance_punches_inmutable BEFORE UPDATE OR DELETE ON attendance_punches FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_attendance_punches_no_truncate BEFORE TRUNCATE ON attendance_punches FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

CREATE TABLE attendance_correction_requests (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  employment_id uuid NOT NULL,
  work_date date NOT NULL,
  requested_by_user_id uuid NOT NULL,
  kind text NOT NULL CHECK (kind IN ('missing_punch','wrong_time','wrong_kind','annul')),
  proposed_punched_at timestamptz,
  proposed_kind text,
  target_punch_id uuid,
  reason text NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','cancelled')),
  workflow_instance_id uuid,
  resolved_by_user_id uuid,
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_attendance_correction_requests_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_attendance_correction_requests_employment_id FOREIGN KEY (tenant_id, employment_id) REFERENCES employments (tenant_id, id),
  CONSTRAINT fk_attendance_correction_requests_requested_by_user_id FOREIGN KEY (tenant_id, requested_by_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_attendance_correction_requests_target_punch_id FOREIGN KEY (tenant_id, target_punch_id) REFERENCES attendance_punches (tenant_id, id),
  CONSTRAINT fk_attendance_correction_requests_workflow_instance_id FOREIGN KEY (tenant_id, workflow_instance_id) REFERENCES workflow_instances (tenant_id, id),
  CONSTRAINT fk_attendance_correction_requests_resolved_by_user_id FOREIGN KEY (tenant_id, resolved_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE attendance_correction_requests IS 'Solicitud de corrección de marcación; al aprobarse genera una marcación nueva, nunca modifica la original.';
CREATE INDEX ix_attendance_correction_requests_employment_id ON attendance_correction_requests (tenant_id, employment_id);
CREATE INDEX ix_attendance_correction_requests_requested_by_user_id ON attendance_correction_requests (tenant_id, requested_by_user_id);
CREATE INDEX ix_attendance_correction_requests_target_punch_id ON attendance_correction_requests (tenant_id, target_punch_id);
CREATE INDEX ix_attendance_correction_requests_workflow_instance_id ON attendance_correction_requests (tenant_id, workflow_instance_id);
CREATE INDEX ix_attendance_correction_requests_resolved_by_user_id ON attendance_correction_requests (tenant_id, resolved_by_user_id);
ALTER TABLE attendance_correction_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_correction_requests FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance_correction_requests USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_attendance_correction_requests_touch BEFORE UPDATE ON attendance_correction_requests FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE attendance_days (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  employment_id uuid NOT NULL,
  work_date date NOT NULL,
  shift_id uuid,
  scheduled_minutes integer,
  worked_minutes integer NOT NULL DEFAULT 0,
  break_minutes integer NOT NULL DEFAULT 0,
  late_minutes integer NOT NULL DEFAULT 0,
  early_leave_minutes integer NOT NULL DEFAULT 0,
  overtime_minutes integer NOT NULL DEFAULT 0,
  overtime_tier1_minutes integer NOT NULL DEFAULT 0,
  overtime_tier2_minutes integer NOT NULL DEFAULT 0,
  night_minutes integer NOT NULL DEFAULT 0,
  holiday_worked boolean NOT NULL DEFAULT false,
  rest_day_worked boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','complete','incomplete','absent','justified','holiday','rest','leave')),
  absence_request_id uuid,
  payroll_period_id uuid,
  is_locked boolean NOT NULL DEFAULT false,
  computed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
