  CONSTRAINT uq_attendance_days_employment_id_work_date UNIQUE (tenant_id, employment_id, work_date),
  CONSTRAINT fk_attendance_days_employment_id FOREIGN KEY (tenant_id, employment_id) REFERENCES employments (tenant_id, id)
);
COMMENT ON TABLE attendance_days IS 'Resumen diario calculado a partir de las marcaciones (recalculable): horas trabajadas, tardanza, sobretiempo, nocturnidad.';
CREATE INDEX ix_attendance_days_shift_id ON attendance_days (tenant_id, shift_id);
CREATE INDEX ix_attendance_days_absence_request_id ON attendance_days (tenant_id, absence_request_id);
CREATE INDEX ix_attendance_days_payroll_period_id ON attendance_days (tenant_id, payroll_period_id);
ALTER TABLE attendance_days ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_days FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance_days USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_attendance_days_touch BEFORE UPDATE ON attendance_days FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE attendance_incidents (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  employment_id uuid NOT NULL,
  attendance_day_id uuid,
