);
COMMENT ON TABLE attendance_incidents IS 'Incidencias de asistencia (tardanza, falta, salida anticipada, marcación faltante) y su justificación.';
CREATE INDEX ix_attendance_incidents_employment_id ON attendance_incidents (tenant_id, employment_id);
