CREATE TABLE labor_regimes (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  code text NOT NULL,
  country_code text NOT NULL,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('general','micro','small','construction','agrarian','training','public','other')),
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
