  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_pension_funds_code UNIQUE (code),
  CONSTRAINT fk_pension_funds_country_code FOREIGN KEY (country_code) REFERENCES countries (code)
);
COMMENT ON TABLE pension_funds IS 'Administradoras y sistemas de pensiones por país.';
