  contribution_rate numeric(7,4),
  commission_flow_rate numeric(7,4),
  commission_mixed_rate numeric(7,4),
  insurance_premium_rate numeric(7,4),
  max_insurable_remuneration numeric(14,2),
  currency char(3),
  source text,
