  valid_from date NOT NULL,
  valid_to date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_pension_fund_rates_vigencia CHECK (valid_to IS NULL OR valid_to >= valid_from),
