  CONSTRAINT fk_pension_fund_rates_pension_fund_id FOREIGN KEY (pension_fund_id) REFERENCES pension_funds (id)
);
COMMENT ON TABLE pension_fund_rates IS 'Tasas por administradora con vigencia (aporte, comisiones, prima, remuneración máxima asegurable). Se cargan de la fuente oficial cada periodo.';
