-- --------------------------------------------------------------------------------------------------
-- PAR · Parámetros legales con vigencia
-- --------------------------------------------------------------------------------------------------

CREATE TABLE legal_parameters (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  country_code text NOT NULL,
  labor_regime_code text,
  code text NOT NULL,
  name text NOT NULL,
  value_numeric numeric(18,6),
  value_json jsonb,
  unit text NOT NULL CHECK (unit IN ('amount','percent','days','business_days','months','years','hours','count','multiple','text','scale')),
  currency char(3),
  valid_from date NOT NULL,
  valid_to date,
  legal_source text,
  verified boolean NOT NULL DEFAULT false,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_legal_parameters_1 CHECK (valid_to IS NULL OR valid_to >= valid_from),
  CONSTRAINT ex_legal_parameters_r1 EXCLUDE USING gist (country_code WITH =, (COALESCE(labor_regime_code, '')) WITH =, code WITH =, daterange(valid_from, valid_to, '[]') WITH &&),
  CONSTRAINT fk_legal_parameters_country_code FOREIGN KEY (country_code) REFERENCES countries (code),
  CONSTRAINT fk_legal_parameters_labor_regime_code FOREIGN KEY (labor_regime_code) REFERENCES labor_regimes (code)
);
COMMENT ON TABLE legal_parameters IS 'Parámetro legal global con vigencia por país y régimen (tasas, topes, plazos). Nunca constantes en código.';
CREATE INDEX ix_legal_parameters_country_code ON legal_parameters (country_code);
CREATE INDEX ix_legal_parameters_labor_regime_code ON legal_parameters (labor_regime_code);
CREATE TRIGGER trg_legal_parameters_touch BEFORE UPDATE ON legal_parameters FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE legal_parameter_overrides (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid,
  parameter_code text NOT NULL,
  value_numeric numeric(18,6),
  value_json jsonb,
  reason text NOT NULL,
  approved_by_user_id uuid,
  valid_from date NOT NULL,
  valid_to date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
