  CONSTRAINT ck_legal_parameter_overrides_vigencia CHECK (valid_to IS NULL OR valid_to >= valid_from),
  CONSTRAINT ex_legal_parameter_overrides_r1 EXCLUDE USING gist (tenant_id WITH =, parameter_code WITH =, (COALESCE(legal_entity_id, '00000000-0000-0000-0000-000000000000'::uuid)) WITH =, daterange(valid_from, valid_to, '[]') WITH &&),
  CONSTRAINT fk_legal_parameter_overrides_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_legal_parameter_overrides_approved_by_user_id FOREIGN KEY (tenant_id, approved_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE legal_parameter_overrides IS 'Valor propio de la organización o de una empresa para un parámetro legal (p. ej. tasa de seguro de riesgo), con vigencia y motivo.';
CREATE INDEX ix_legal_parameter_overrides_legal_entity_id ON legal_parameter_overrides (tenant_id, legal_entity_id);
CREATE INDEX ix_legal_parameter_overrides_approved_by_user_id ON legal_parameter_overrides (tenant_id, approved_by_user_id);
ALTER TABLE legal_parameter_overrides ENABLE ROW LEVEL SECURITY;
ALTER TABLE legal_parameter_overrides FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON legal_parameter_overrides USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
