  kind text NOT NULL DEFAULT 'regular' CHECK (kind IN ('regular','gratification','cts','profit_sharing','settlement','special')),
  starts_on date NOT NULL,
  ends_on date NOT NULL,
  payment_date date,
  attendance_from date,
  attendance_to date,
  statutory_period_code text,
