  CONSTRAINT fk_judicial_withholdings_document_id FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id)
);
COMMENT ON TABLE judicial_withholdings IS 'Retenciones por mandato judicial (alimentos, embargos); datos del expediente y del beneficiario cifrados. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
