CREATE TABLE statutory_filings (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  kind text NOT NULL CHECK (kind IN ('plame','t_registro','afpnet','cts_report','profit_sharing','withholding_certificates','other')),
  period_code text NOT NULL,
  payroll_period_id uuid,
  is_rectification boolean NOT NULL DEFAULT false,
  rectifies_filing_id uuid,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','generated','validated','with_errors','submitted','accepted','rejected','observed','rectified')),
  validation_report jsonb,
  submitted_at timestamptz,
  submitted_by_user_id uuid,
  external_reference text,
  due_on date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_statutory_filings_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_statutory_filings_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_statutory_filings_payroll_period_id FOREIGN KEY (tenant_id, payroll_period_id) REFERENCES payroll_periods (tenant_id, id),
  CONSTRAINT fk_statutory_filings_rectifies_filing_id FOREIGN KEY (tenant_id, rectifies_filing_id) REFERENCES statutory_filings (tenant_id, id),
  CONSTRAINT fk_statutory_filings_submitted_by_user_id FOREIGN KEY (tenant_id, submitted_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE statutory_filings IS 'Declaración o archivo oficial por empresa y periodo (planilla electrónica, registro laboral, aportes previsionales), con validación previa y rectificatorias.';
CREATE INDEX ix_statutory_filings_legal_entity_id ON statutory_filings (tenant_id, legal_entity_id);
CREATE INDEX ix_statutory_filings_payroll_period_id ON statutory_filings (tenant_id, payroll_period_id);
CREATE INDEX ix_statutory_filings_rectifies_filing_id ON statutory_filings (tenant_id, rectifies_filing_id);
CREATE INDEX ix_statutory_filings_submitted_by_user_id ON statutory_filings (tenant_id, submitted_by_user_id);
ALTER TABLE statutory_filings ENABLE ROW LEVEL SECURITY;
ALTER TABLE statutory_filings FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON statutory_filings USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_statutory_filings_touch BEFORE UPDATE ON statutory_filings FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE statutory_filing_files (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  statutory_filing_id uuid NOT NULL,
  file_kind text NOT NULL,
  stored_file_id uuid NOT NULL,
  record_count integer,
  checksum text,
  statutory_file_layout_id uuid,
  file_name text,
  sha256 text,
  byte_size bigint,
  control_totals jsonb,
  generator_version text,
  generated_by_user_id uuid,
  supersedes_file_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_statutory_filing_files_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT ck_statutory_filing_files_1 CHECK (sha256 IS NULL OR sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT ck_statutory_filing_files_2 CHECK (byte_size IS NULL OR byte_size >= 0),
  CONSTRAINT fk_statutory_filing_files_statutory_filing_id FOREIGN KEY (tenant_id, statutory_filing_id) REFERENCES statutory_filings (tenant_id, id),
  CONSTRAINT fk_statutory_filing_files_stored_file_id FOREIGN KEY (tenant_id, stored_file_id) REFERENCES stored_files (tenant_id, id),
  CONSTRAINT fk_statutory_filing_files_generated_by_user_id FOREIGN KEY (tenant_id, generated_by_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_statutory_filing_files_supersedes_file_id FOREIGN KEY (tenant_id, supersedes_file_id) REFERENCES statutory_filing_files (tenant_id, id)
);
COMMENT ON TABLE statutory_filing_files IS 'Archivos generados de una declaración.';
CREATE INDEX ix_statutory_filing_files_statutory_filing_id ON statutory_filing_files (tenant_id, statutory_filing_id);
CREATE INDEX ix_statutory_filing_files_stored_file_id ON statutory_filing_files (tenant_id, stored_file_id);
CREATE INDEX ix_statutory_filing_files_statutory_file_layout_id ON statutory_filing_files (tenant_id, statutory_file_layout_id);
CREATE INDEX ix_statutory_filing_files_generated_by_user_id ON statutory_filing_files (tenant_id, generated_by_user_id);
CREATE INDEX ix_statutory_filing_files_supersedes_file_id ON statutory_filing_files (tenant_id, supersedes_file_id);
ALTER TABLE statutory_filing_files ENABLE ROW LEVEL SECURITY;
ALTER TABLE statutory_filing_files FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON statutory_filing_files USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_statutory_filing_files_touch BEFORE UPDATE ON statutory_filing_files FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE statutory_file_layouts (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  country_code text NOT NULL,
  filing_kind text NOT NULL,
  structure_code text NOT NULL,
  name text NOT NULL,
  file_name_pattern text NOT NULL,
  file_extension text,
  layout_version text NOT NULL,
  field_separator text,
  encoding text NOT NULL DEFAULT 'ISO-8859-1',
  line_ending text NOT NULL DEFAULT 'CRLF' CHECK (line_ending IN ('CRLF','LF')),
  has_header boolean NOT NULL DEFAULT false,
  trailing_separator boolean NOT NULL DEFAULT true,
  fields jsonb NOT NULL,
  source text,
  verified boolean NOT NULL DEFAULT false,
  valid_from date NOT NULL,
  valid_to date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_statutory_file_layouts_vigencia CHECK (valid_to IS NULL OR valid_to >= valid_from),
  CONSTRAINT ck_statutory_file_layouts_1 CHECK (jsonb_typeof(fields) = 'array' AND jsonb_array_length(fields) > 0),
  CONSTRAINT ex_statutory_file_layouts_vigencia EXCLUDE USING gist (country_code WITH =, filing_kind WITH =, structure_code WITH =, daterange(valid_from, valid_to, '[]') WITH &&) DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_statutory_file_layouts_country_code FOREIGN KEY (country_code) REFERENCES countries (code)
);
COMMENT ON TABLE statutory_file_layouts IS 'Estructura campo por campo de cada archivo oficial, con vigencia. fields = lista de campos con número, nombre, tipo, longitud máxima, decimales, obligatoriedad y tabla paramétrica.';
CREATE TRIGGER trg_statutory_file_layouts_touch BEFORE UPDATE ON statutory_file_layouts FOR EACH ROW EXECUTE FUNCTION set_updated_at();

