  CONSTRAINT fk_registry_events_confirmation_document_id FOREIGN KEY (tenant_id, confirmation_document_id) REFERENCES documents (tenant_id, id)
);
COMMENT ON TABLE registry_events IS 'Altas, bajas y modificaciones de trabajadores, practicantes y derechohabientes pendientes ante el registro laboral, con plazo.';
CREATE INDEX ix_registry_events_legal_entity_id ON registry_events (tenant_id, legal_entity_id);
CREATE INDEX ix_registry_events_employment_id ON registry_events (tenant_id, employment_id);
CREATE INDEX ix_registry_events_dependent_id ON registry_events (tenant_id, dependent_id);
CREATE INDEX ix_registry_events_statutory_filing_id ON registry_events (tenant_id, statutory_filing_id);
CREATE INDEX ix_registry_events_confirmation_document_id ON registry_events (tenant_id, confirmation_document_id);
ALTER TABLE registry_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE registry_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON registry_events USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
