  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  journal_entry_id uuid,
  format text NOT NULL,
  integration_id uuid,
  stored_file_id uuid,
  status text NOT NULL DEFAULT 'generated' CHECK (status IN ('generated','sent','acknowledged','failed')),
  exported_by_user_id uuid,
  external_reference text,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_accounting_exports_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_accounting_exports_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_accounting_exports_journal_entry_id FOREIGN KEY (tenant_id, journal_entry_id) REFERENCES journal_entries (tenant_id, id),
  CONSTRAINT fk_accounting_exports_stored_file_id FOREIGN KEY (tenant_id, stored_file_id) REFERENCES stored_files (tenant_id, id),
  CONSTRAINT fk_accounting_exports_exported_by_user_id FOREIGN KEY (tenant_id, exported_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE accounting_exports IS 'Exportación de asientos al ERP o a archivo contable.';
CREATE INDEX ix_accounting_exports_legal_entity_id ON accounting_exports (tenant_id, legal_entity_id);
CREATE INDEX ix_accounting_exports_journal_entry_id ON accounting_exports (tenant_id, journal_entry_id);
CREATE INDEX ix_accounting_exports_integration_id ON accounting_exports (tenant_id, integration_id);
CREATE INDEX ix_accounting_exports_stored_file_id ON accounting_exports (tenant_id, stored_file_id);
CREATE INDEX ix_accounting_exports_exported_by_user_id ON accounting_exports (tenant_id, exported_by_user_id);
ALTER TABLE accounting_exports ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounting_exports FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON accounting_exports USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
