-- --------------------------------------------------------------------------------------------------
-- LIQ · Liquidación de beneficios
-- --------------------------------------------------------------------------------------------------

CREATE TABLE settlements (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  employment_id uuid NOT NULL,
  termination_id uuid,
  is_simulation boolean NOT NULL DEFAULT false,
  termination_date date NOT NULL,
  reason_code text,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','calculated','approved','paid','voided','pending_approval','documents_delivered')),
  total_amount numeric(14,2),  -- SENSIBLE
  currency char(3) NOT NULL,
  due_on date,
  paid_on date,
  payroll_run_id uuid,
  parameters_snapshot jsonb,
  document_id uuid,
  approved_by_user_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_settlements_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_settlements_employment_id FOREIGN KEY (tenant_id, employment_id) REFERENCES employments (tenant_id, id),
  CONSTRAINT fk_settlements_payroll_run_id FOREIGN KEY (tenant_id, payroll_run_id) REFERENCES payroll_runs (tenant_id, id),
  CONSTRAINT fk_settlements_document_id FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id),
  CONSTRAINT fk_settlements_approved_by_user_id FOREIGN KEY (tenant_id, approved_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE settlements IS 'Liquidación de beneficios sociales al cese o su simulación (E-04). -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE INDEX ix_settlements_employment_id ON settlements (tenant_id, employment_id);
CREATE INDEX ix_settlements_termination_id ON settlements (tenant_id, termination_id);
CREATE INDEX ix_settlements_payroll_run_id ON settlements (tenant_id, payroll_run_id);
CREATE INDEX ix_settlements_document_id ON settlements (tenant_id, document_id);
CREATE INDEX ix_settlements_approved_by_user_id ON settlements (tenant_id, approved_by_user_id);
ALTER TABLE settlements ENABLE ROW LEVEL SECURITY;
ALTER TABLE settlements FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON settlements USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_settlements_touch BEFORE UPDATE ON settlements FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE settlement_lines (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  settlement_id uuid NOT NULL,
  kind text NOT NULL CHECK (kind IN ('cts_truncated','vacation_truncated','vacation_unused','vacation_indemnity','gratification_truncated','extraordinary_bonus','severance_indemnity','pending_salary','loan_balance','advance_balance','other_earning','other_deduction','tax','contribution')),
  payroll_concept_id uuid,
  base_amount numeric(14,2),
  quantity numeric(12,4),
  amount numeric(14,2) NOT NULL,  -- SENSIBLE
  currency char(3) NOT NULL,
  trace jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_settlement_lines_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_settlement_lines_settlement_id FOREIGN KEY (tenant_id, settlement_id) REFERENCES settlements (tenant_id, id),
  CONSTRAINT fk_settlement_lines_payroll_concept_id FOREIGN KEY (tenant_id, payroll_concept_id) REFERENCES payroll_concepts (tenant_id, id)
);
COMMENT ON TABLE settlement_lines IS 'Líneas de la liquidación (truncos, vacaciones no gozadas, indemnización, saldos por descontar), con traza. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE INDEX ix_settlement_lines_settlement_id ON settlement_lines (tenant_id, settlement_id);
CREATE INDEX ix_settlement_lines_payroll_concept_id ON settlement_lines (tenant_id, payroll_concept_id);
ALTER TABLE settlement_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE settlement_lines FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON settlement_lines USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_settlement_lines_touch BEFORE UPDATE ON settlement_lines FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE termination_documents (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  employment_id uuid NOT NULL,
  settlement_id uuid,
  kind text NOT NULL CHECK (kind IN ('work_certificate','cts_release_letter','termination_record','settlement_statement','withholding_certificate')),
  document_id uuid NOT NULL,
