CREATE TABLE contractors (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  person_id uuid,
  legal_entity_id uuid NOT NULL,
  business_name text,
  tax_id_enc text NOT NULL,  -- SENSIBLE (cifrado en la aplicación)
  tax_id_hash text NOT NULL,
  service_description text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  has_withholding_suspension boolean NOT NULL DEFAULT false,
  suspension_valid_until date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_contractors_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_contractors_person_id FOREIGN KEY (tenant_id, person_id) REFERENCES people (tenant_id, id),
  CONSTRAINT fk_contractors_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id)
);
COMMENT ON TABLE contractors IS 'Prestador de servicios independiente (E-18), separado de la planilla.';
CREATE INDEX ix_contractors_person_id ON contractors (tenant_id, person_id);
CREATE INDEX ix_contractors_legal_entity_id ON contractors (tenant_id, legal_entity_id);
ALTER TABLE contractors ENABLE ROW LEVEL SECURITY;
ALTER TABLE contractors FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON contractors USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_contractors_touch BEFORE UPDATE ON contractors FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE contractor_engagements (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
