  CONSTRAINT fk_contractor_engagements_org_unit_id FOREIGN KEY (tenant_id, org_unit_id) REFERENCES org_units (tenant_id, id),
  CONSTRAINT fk_contractor_engagements_cost_center_id FOREIGN KEY (tenant_id, cost_center_id) REFERENCES cost_centers (tenant_id, id),
  CONSTRAINT fk_contractor_engagements_document_id FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id)
);
COMMENT ON TABLE contractor_engagements IS 'Encargo o contrato de locación de servicios.';
CREATE INDEX ix_contractor_engagements_contractor_id ON contractor_engagements (tenant_id, contractor_id);
CREATE INDEX ix_contractor_engagements_org_unit_id ON contractor_engagements (tenant_id, org_unit_id);
CREATE INDEX ix_contractor_engagements_cost_center_id ON contractor_engagements (tenant_id, cost_center_id);
CREATE INDEX ix_contractor_engagements_document_id ON contractor_engagements (tenant_id, document_id);
ALTER TABLE contractor_engagements ENABLE ROW LEVEL SECURITY;
ALTER TABLE contractor_engagements FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON contractor_engagements USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
