CREATE INDEX ix_contractor_invoices_contractor_engagement_id ON contractor_invoices (tenant_id, contractor_engagement_id);
CREATE INDEX ix_contractor_invoices_file_id ON contractor_invoices (tenant_id, file_id);
CREATE INDEX ix_contractor_invoices_approved_by_user_id ON contractor_invoices (tenant_id, approved_by_user_id);
CREATE INDEX ix_contractor_invoices_payroll_payment_item_id ON contractor_invoices (tenant_id, payroll_payment_item_id);
ALTER TABLE contractor_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE contractor_invoices FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON contractor_invoices USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
