CREATE TABLE job_requisitions (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  code text NOT NULL,
  title text NOT NULL,
  position_id uuid,
  position_request_id uuid,
  job_profile_id uuid,
  org_unit_id uuid,
  site_id uuid,
  legal_entity_id uuid,
  hiring_manager_user_id uuid,
  recruiter_user_id uuid,
  openings smallint NOT NULL DEFAULT 1,
  employment_kind text,
  work_modality text CHECK (work_modality IN ('onsite','remote','hybrid')),
  salary_min numeric(14,2),  -- SENSIBLE
  salary_max numeric(14,2),  -- SENSIBLE
  currency char(3),
  description text,
  requirements text,
  benefits_text text,
  recruitment_pipeline_id uuid,
