  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_job_requisitions_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_job_requisitions_position_id FOREIGN KEY (tenant_id, position_id) REFERENCES positions (tenant_id, id),
  CONSTRAINT fk_job_requisitions_position_request_id FOREIGN KEY (tenant_id, position_request_id) REFERENCES position_requests (tenant_id, id),
  CONSTRAINT fk_job_requisitions_job_profile_id FOREIGN KEY (tenant_id, job_profile_id) REFERENCES job_profiles (tenant_id, id),
  CONSTRAINT fk_job_requisitions_org_unit_id FOREIGN KEY (tenant_id, org_unit_id) REFERENCES org_units (tenant_id, id),
  CONSTRAINT fk_job_requisitions_site_id FOREIGN KEY (tenant_id, site_id) REFERENCES sites (tenant_id, id),
  CONSTRAINT fk_job_requisitions_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_job_requisitions_hiring_manager_user_id FOREIGN KEY (tenant_id, hiring_manager_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_job_requisitions_recruiter_user_id FOREIGN KEY (tenant_id, recruiter_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_job_requisitions_recruitment_pipeline_id FOREIGN KEY (tenant_id, recruitment_pipeline_id) REFERENCES recruitment_pipelines (tenant_id, id),
  CONSTRAINT fk_job_requisitions_workflow_instance_id FOREIGN KEY (tenant_id, workflow_instance_id) REFERENCES workflow_instances (tenant_id, id)
);
COMMENT ON TABLE job_requisitions IS 'Vacante: se abre contra una posición o una solicitud aprobada cuando la política lo exige.';
