CREATE INDEX ix_job_requisitions_site_id ON job_requisitions (tenant_id, site_id);
CREATE INDEX ix_job_requisitions_legal_entity_id ON job_requisitions (tenant_id, legal_entity_id);
CREATE INDEX ix_job_requisitions_hiring_manager_user_id ON job_requisitions (tenant_id, hiring_manager_user_id);
CREATE INDEX ix_job_requisitions_recruiter_user_id ON job_requisitions (tenant_id, recruiter_user_id);
CREATE INDEX ix_job_requisitions_recruitment_pipeline_id ON job_requisitions (tenant_id, recruitment_pipeline_id);
