  CONSTRAINT ck_sst_election_participants_1 CHECK ((role = 'candidate') = (candidacy_status IS NOT NULL)),
  CONSTRAINT ck_sst_election_participants_2 CHECK (votes IS NULL OR votes >= 0),
  CONSTRAINT fk_sst_election_participants_sst_committee_election_id FOREIGN KEY (tenant_id, sst_committee_election_id) REFERENCES sst_committee_elections (tenant_id, id),
