CREATE TABLE complaints (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  complaint_channel_id uuid NOT NULL,
  legal_entity_id uuid,
  tracking_code_hash text NOT NULL,
  access_secret_hash text NOT NULL,
  is_anonymous boolean NOT NULL,
  category text NOT NULL CHECK (category IN ('sexual_harassment','workplace_harassment','discrimination','fraud','corruption','safety','ethics','retaliation','other')),
  description_enc text NOT NULL,  -- SENSIBLE (cifrado en la aplicación)
  involved_people_enc text,  -- SENSIBLE (cifrado en la aplicación)
  incident_period_text text,
  location_text_enc text,  -- SENSIBLE (cifrado en la aplicación)
  status text NOT NULL DEFAULT 'received' CHECK (status IN ('received','admitted','under_investigation','protection_measures','resolved','dismissed','closed','report_issued')),
  severity text CHECK (severity IN ('low','medium','high','critical')),
  received_on date NOT NULL,
  admitted_on date,
  due_on date,
  resolved_on date,
  resolution_enc text,  -- SENSIBLE (cifrado en la aplicación)
  harassment_committee_id uuid,
  procedure_stage text CHECK (procedure_stage IN ('received','referred_to_committee','investigating','report_issued','decided','closed')),
  started_ex_officio boolean NOT NULL DEFAULT false,
  ledger_chain_key text,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_complaints_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_complaints_tracking_code_hash UNIQUE (tenant_id, tracking_code_hash),
  CONSTRAINT fk_complaints_complaint_channel_id FOREIGN KEY (tenant_id, complaint_channel_id) REFERENCES complaint_channels (tenant_id, id),
  CONSTRAINT fk_complaints_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_complaints_harassment_committee_id FOREIGN KEY (tenant_id, harassment_committee_id) REFERENCES harassment_committees (tenant_id, id)
);
COMMENT ON TABLE complaints IS 'Denuncia (C-06). NO guarda usuario, persona, IP, agente de navegador ni marcas de hora: solo la fecha y huellas del código de seguimiento. Contenido cifrado. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE INDEX ix_complaints_complaint_channel_id ON complaints (tenant_id, complaint_channel_id);
CREATE INDEX ix_complaints_legal_entity_id ON complaints (tenant_id, legal_entity_id);
CREATE INDEX ix_complaints_harassment_committee_id ON complaints (tenant_id, harassment_committee_id);
ALTER TABLE complaints ENABLE ROW LEVEL SECURITY;
ALTER TABLE complaints FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON complaints USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
