  read_by_counterpart boolean NOT NULL DEFAULT false,
  CONSTRAINT uq_complaint_messages_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT ck_complaint_messages_1 CHECK (author_kind <> 'reporter' OR investigator_user_id IS NULL),
  CONSTRAINT fk_complaint_messages_complaint_id FOREIGN KEY (tenant_id, complaint_id) REFERENCES complaints (tenant_id, id),
  CONSTRAINT fk_complaint_messages_investigator_user_id FOREIGN KEY (tenant_id, investigator_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE complaint_messages IS 'Mensajes entre el denunciante (por código de seguimiento) y los investigadores; cifrados y solo con fecha. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE INDEX ix_complaint_messages_complaint_id ON complaint_messages (tenant_id, complaint_id);
CREATE INDEX ix_complaint_messages_investigator_user_id ON complaint_messages (tenant_id, investigator_user_id);
ALTER TABLE complaint_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE complaint_messages FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON complaint_messages USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

