CREATE TABLE disciplinary_cases (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  employment_id uuid NOT NULL,
  number text NOT NULL,
  opened_on date NOT NULL,
  kind text NOT NULL CHECK (kind IN ('misconduct','performance','attendance','policy_violation','other')),
  summary_enc text NOT NULL,  -- SENSIBLE (cifrado en la aplicación)
  severity text CHECK (severity IN ('minor','serious','very_serious')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','charges_notified','defense_received','under_review','sanctioned','dismissed','closed','awaiting_defense','decided')),
  owner_user_id uuid,
  defense_due_on date,
  closed_on date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_disciplinary_cases_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_disciplinary_cases_employment_id FOREIGN KEY (tenant_id, employment_id) REFERENCES employments (tenant_id, id),
  CONSTRAINT fk_disciplinary_cases_owner_user_id FOREIGN KEY (tenant_id, owner_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE disciplinary_cases IS 'Caso disciplinario; información altamente confidencial, cifrada. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE UNIQUE INDEX uq_disciplinary_cases_number ON disciplinary_cases (tenant_id, number) WHERE deleted_at IS NULL;
CREATE INDEX ix_disciplinary_cases_employment_id ON disciplinary_cases (tenant_id, employment_id);
CREATE INDEX ix_disciplinary_cases_owner_user_id ON disciplinary_cases (tenant_id, owner_user_id);
ALTER TABLE disciplinary_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE disciplinary_cases FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON disciplinary_cases USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_disciplinary_cases_touch BEFORE UPDATE ON disciplinary_cases FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE disciplinary_case_events (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
