CREATE TABLE inspection_cases (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  authority text NOT NULL DEFAULT 'sunafil' CHECK (authority IN ('sunafil','mtpe','essalud','municipal','other')),
  case_number text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('inspection_order','requirement','infraction_record','sanction_procedure','other')),
  subject text,
  opened_on date NOT NULL,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','responding','hearing','resolved','sanctioned','appealed','closed')),
  responsible_user_id uuid,
  fine_amount numeric(14,2),
  currency char(3),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_inspection_cases_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_inspection_cases_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_inspection_cases_responsible_user_id FOREIGN KEY (tenant_id, responsible_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE inspection_cases IS 'Actuación de la autoridad inspectiva: orden, requerimiento, acta o procedimiento sancionador (E-02).';
CREATE INDEX ix_inspection_cases_legal_entity_id ON inspection_cases (tenant_id, legal_entity_id);
CREATE INDEX ix_inspection_cases_responsible_user_id ON inspection_cases (tenant_id, responsible_user_id);
ALTER TABLE inspection_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE inspection_cases FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON inspection_cases USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_inspection_cases_touch BEFORE UPDATE ON inspection_cases FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE inspection_requirements (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  inspection_case_id uuid NOT NULL,
  description text NOT NULL,
  due_at timestamptz NOT NULL,
  responsible_user_id uuid,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','submitted','overdue')),
  submitted_at timestamptz,
  response_document_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_inspection_requirements_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_inspection_requirements_inspection_case_id FOREIGN KEY (tenant_id, inspection_case_id) REFERENCES inspection_cases (tenant_id, id),
  CONSTRAINT fk_inspection_requirements_responsible_user_id FOREIGN KEY (tenant_id, responsible_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_inspection_requirements_response_document_id FOREIGN KEY (tenant_id, response_document_id) REFERENCES documents (tenant_id, id)
);
COMMENT ON TABLE inspection_requirements IS 'Requerimientos de información de una inspección, con responsable y plazo.';
CREATE INDEX ix_inspection_requirements_inspection_case_id ON inspection_requirements (tenant_id, inspection_case_id);
CREATE INDEX ix_inspection_requirements_responsible_user_id ON inspection_requirements (tenant_id, responsible_user_id);
CREATE INDEX ix_inspection_requirements_response_document_id ON inspection_requirements (tenant_id, response_document_id);
ALTER TABLE inspection_requirements ENABLE ROW LEVEL SECURITY;
ALTER TABLE inspection_requirements FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON inspection_requirements USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_inspection_requirements_touch BEFORE UPDATE ON inspection_requirements FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE mailbox_notices (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  authority text NOT NULL DEFAULT 'sunafil' CHECK (authority IN ('sunafil','mtpe','sunat','other')),
  notice_reference text NOT NULL,
  received_on date NOT NULL,
  effective_on date,
  subject text,
  document_id uuid,
  inspection_case_id uuid,
  responsible_user_id uuid,
  due_on date,
  status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','assigned','answered','archived','in_preparation','overdue')),
  read_at timestamptz,
  deposited_at timestamptz,
  notice_kind text CHECK (notice_kind IN ('information_requirement','appearance_summons','inspection_measure','infraction_record','charges','final_report','resolution','coercive','other')),
  response_days numeric(6,2),
  response_day_kind text CHECK (response_day_kind IN ('business','calendar')),
  captured_by_user_id uuid,
  content_sha256 text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_mailbox_notices_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_mailbox_notices_legal_entity_id_authority_notice_reference UNIQUE (tenant_id, legal_entity_id, authority, notice_reference),
  CONSTRAINT ck_mailbox_notices_1 CHECK (content_sha256 IS NULL OR content_sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT fk_mailbox_notices_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_mailbox_notices_document_id FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id),
  CONSTRAINT fk_mailbox_notices_inspection_case_id FOREIGN KEY (tenant_id, inspection_case_id) REFERENCES inspection_cases (tenant_id, id),
  CONSTRAINT fk_mailbox_notices_responsible_user_id FOREIGN KEY (tenant_id, responsible_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_mailbox_notices_captured_by_user_id FOREIGN KEY (tenant_id, captured_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE mailbox_notices IS 'Bandeja de la casilla electrónica: notificaciones recibidas con responsable y plazo (E-02).';
CREATE INDEX ix_mailbox_notices_document_id ON mailbox_notices (tenant_id, document_id);
CREATE INDEX ix_mailbox_notices_inspection_case_id ON mailbox_notices (tenant_id, inspection_case_id);
CREATE INDEX ix_mailbox_notices_responsible_user_id ON mailbox_notices (tenant_id, responsible_user_id);
CREATE INDEX ix_mailbox_notices_captured_by_user_id ON mailbox_notices (tenant_id, captured_by_user_id);
ALTER TABLE mailbox_notices ENABLE ROW LEVEL SECURITY;
ALTER TABLE mailbox_notices FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON mailbox_notices USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_mailbox_notices_touch BEFORE UPDATE ON mailbox_notices FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE inspection_dossiers (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  inspection_case_id uuid,
  title text NOT NULL,
  period_from date NOT NULL,
  period_to date NOT NULL,
  dossier_scope jsonb,
  status text NOT NULL DEFAULT 'building' CHECK (status IN ('building','ready','exported','failed')),
  stored_file_id uuid,
  generated_by_user_id uuid,
  generated_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_inspection_dossiers_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_inspection_dossiers_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_inspection_dossiers_inspection_case_id FOREIGN KEY (tenant_id, inspection_case_id) REFERENCES inspection_cases (tenant_id, id),
  CONSTRAINT fk_inspection_dossiers_stored_file_id FOREIGN KEY (tenant_id, stored_file_id) REFERENCES stored_files (tenant_id, id),
  CONSTRAINT fk_inspection_dossiers_generated_by_user_id FOREIGN KEY (tenant_id, generated_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE inspection_dossiers IS 'Expediente de inspección exportable por trabajador y periodo (E-02).';
CREATE INDEX ix_inspection_dossiers_legal_entity_id ON inspection_dossiers (tenant_id, legal_entity_id);
CREATE INDEX ix_inspection_dossiers_inspection_case_id ON inspection_dossiers (tenant_id, inspection_case_id);
CREATE INDEX ix_inspection_dossiers_stored_file_id ON inspection_dossiers (tenant_id, stored_file_id);
CREATE INDEX ix_inspection_dossiers_generated_by_user_id ON inspection_dossiers (tenant_id, generated_by_user_id);
ALTER TABLE inspection_dossiers ENABLE ROW LEVEL SECURITY;
ALTER TABLE inspection_dossiers FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON inspection_dossiers USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_inspection_dossiers_touch BEFORE UPDATE ON inspection_dossiers FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE inspection_dossier_items (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  inspection_dossier_id uuid NOT NULL,
  employment_id uuid,
  section text NOT NULL CHECK (section IN ('payslips','attendance','contracts','safety','certificates','insurance','other')),
  document_id uuid,
  source_type text,
  source_id uuid,
  period_code text,
  is_missing boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_inspection_dossier_items_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_inspection_dossier_items_inspection_dossier_id FOREIGN KEY (tenant_id, inspection_dossier_id) REFERENCES inspection_dossiers (tenant_id, id),
  CONSTRAINT fk_inspection_dossier_items_employment_id FOREIGN KEY (tenant_id, employment_id) REFERENCES employments (tenant_id, id),
  CONSTRAINT fk_inspection_dossier_items_document_id FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id)
);
COMMENT ON TABLE inspection_dossier_items IS 'Piezas del expediente (boletas, asistencia, contratos, SST, constancias) y marca de faltante.';
CREATE INDEX ix_inspection_dossier_items_inspection_dossier_id ON inspection_dossier_items (tenant_id, inspection_dossier_id);
CREATE INDEX ix_inspection_dossier_items_employment_id ON inspection_dossier_items (tenant_id, employment_id);
CREATE INDEX ix_inspection_dossier_items_document_id ON inspection_dossier_items (tenant_id, document_id);
ALTER TABLE inspection_dossier_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE inspection_dossier_items FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON inspection_dossier_items USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_inspection_dossier_items_touch BEFORE UPDATE ON inspection_dossier_items FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE compliance_ledger_entries (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  chain_key text NOT NULL,
  seq bigint NOT NULL,
  entry_type text NOT NULL,
  subject_type text NOT NULL,
  subject_id uuid NOT NULL,
  payload jsonb NOT NULL,  -- SENSIBLE
  payload_canonical text NOT NULL,  -- SENSIBLE
  payload_hash text NOT NULL,
  prev_hash text NOT NULL,
  entry_hash text NOT NULL,
  hash_algorithm text NOT NULL DEFAULT 'SHA-256',
  actor_kind text NOT NULL CHECK (actor_kind IN ('user','system','anonymous_reporter','committee')),
  actor_user_id uuid,
  signer_role text,
  signature_event_id uuid,
  occurred_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  timestamp_token bytea,
  timestamp_authority text,
  retain_until date,
  CONSTRAINT uq_compliance_ledger_entries_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_compliance_ledger_entries_chain_key_seq UNIQUE (tenant_id, chain_key, seq),
  CONSTRAINT uq_compliance_ledger_entries_chain_key_entry_hash UNIQUE (tenant_id, chain_key, entry_hash),
  CONSTRAINT ck_compliance_ledger_entries_1 CHECK (seq >= 1),
  CONSTRAINT ck_compliance_ledger_entries_2 CHECK (payload_hash ~ '^[0-9a-f]{64}$' AND prev_hash ~ '^[0-9a-f]{64}$' AND entry_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT ck_compliance_ledger_entries_3 CHECK (payload_canonical::jsonb = payload),
  CONSTRAINT ck_compliance_ledger_entries_4 CHECK (actor_kind <> 'anonymous_reporter' OR (actor_user_id IS NULL AND signature_event_id IS NULL)),
  CONSTRAINT ck_compliance_ledger_entries_5 CHECK (actor_kind <> 'user' OR actor_user_id IS NOT NULL),
  CONSTRAINT fk_compliance_ledger_entries_actor_user_id FOREIGN KEY (tenant_id, actor_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_compliance_ledger_entries_signature_event_id FOREIGN KEY (tenant_id, signature_event_id) REFERENCES signature_events (tenant_id, id)
);
COMMENT ON TABLE compliance_ledger_entries IS 'Registro inalterable de actos de cumplimiento (comités, elecciones, actas, procedimiento de hostigamiento, casilla). Cada fila guarda la huella de la anterior de su cadena. Sin IP, agente de usuario ni sesión. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE INDEX ix_compliance_ledger_entries_actor_user_id ON compliance_ledger_entries (tenant_id, actor_user_id);
CREATE INDEX ix_compliance_ledger_entries_signature_event_id ON compliance_ledger_entries (tenant_id, signature_event_id);
CREATE INDEX ix_compliance_ledger_entries_subject_type_subject_id ON compliance_ledger_entries (tenant_id, subject_type, subject_id);
ALTER TABLE compliance_ledger_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE compliance_ledger_entries FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON compliance_ledger_entries USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_compliance_ledger_entries_inmutable BEFORE UPDATE OR DELETE ON compliance_ledger_entries FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_compliance_ledger_entries_no_truncate BEFORE TRUNCATE ON compliance_ledger_entries FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

CREATE TABLE compliance_ledger_anchors (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  anchored_at timestamptz NOT NULL DEFAULT now(),
  chain_heads jsonb NOT NULL,
  root_hash text NOT NULL,
  timestamp_token bytea,
  timestamp_authority text,
  CONSTRAINT uq_compliance_ledger_anchors_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT ck_compliance_ledger_anchors_1 CHECK (root_hash ~ '^[0-9a-f]{64}$')
);
COMMENT ON TABLE compliance_ledger_anchors IS 'Huella raíz de todas las cabezas de cadena de la organización en un instante, sellada por una autoridad de sellado de tiempo.';
ALTER TABLE compliance_ledger_anchors ENABLE ROW LEVEL SECURITY;
ALTER TABLE compliance_ledger_anchors FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON compliance_ledger_anchors USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_compliance_ledger_anchors_inmutable BEFORE UPDATE OR DELETE ON compliance_ledger_anchors FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_compliance_ledger_anchors_no_truncate BEFORE TRUNCATE ON compliance_ledger_anchors FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

CREATE TABLE compliance_deadlines (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  subject_type text NOT NULL,
  subject_id uuid NOT NULL,
  deadline_code text NOT NULL,
  parameter_code text NOT NULL,
  parameter_value numeric(18,6) NOT NULL,
  day_kind text NOT NULL CHECK (day_kind IN ('business','calendar','hours')),
  starts_at timestamptz NOT NULL,
  due_at timestamptz NOT NULL,
  met_at timestamptz,
  responsible_user_id uuid,
  status text NOT NULL DEFAULT 'running' CHECK (status IN ('running','met','met_late','overdue','cancelled')),
  ledger_entry_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_compliance_deadlines_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_compliance_deadlines_subject_type_subject_id_deadline_code UNIQUE (tenant_id, subject_type, subject_id, deadline_code),
  CONSTRAINT ck_compliance_deadlines_1 CHECK (due_at >= starts_at),
  CONSTRAINT fk_compliance_deadlines_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_compliance_deadlines_responsible_user_id FOREIGN KEY (tenant_id, responsible_user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_compliance_deadlines_ledger_entry_id FOREIGN KEY (tenant_id, ledger_entry_id) REFERENCES compliance_ledger_entries (tenant_id, id)
);
COMMENT ON TABLE compliance_deadlines IS 'Plazo legal en curso sobre un sujeto: guarda el parámetro y el valor con que se calculó el vencimiento, para que un cambio posterior del parámetro no altere plazos ya iniciados.';
CREATE INDEX ix_compliance_deadlines_legal_entity_id ON compliance_deadlines (tenant_id, legal_entity_id);
CREATE INDEX ix_compliance_deadlines_responsible_user_id ON compliance_deadlines (tenant_id, responsible_user_id);
CREATE INDEX ix_compliance_deadlines_ledger_entry_id ON compliance_deadlines (tenant_id, ledger_entry_id);
CREATE INDEX ix_compliance_deadlines_status_due_at ON compliance_deadlines (tenant_id, status, due_at);
ALTER TABLE compliance_deadlines ENABLE ROW LEVEL SECURITY;
ALTER TABLE compliance_deadlines FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON compliance_deadlines USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_compliance_deadlines_touch BEFORE UPDATE ON compliance_deadlines FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE authority_communications (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  authority text NOT NULL CHECK (authority IN ('mtpe','sunafil','sunat','essalud','other')),
  subject_type text NOT NULL,
  subject_id uuid NOT NULL,
  kind text NOT NULL CHECK (kind IN ('harassment_complaint_received','harassment_decision','work_accident','committee_installation','requirement_response','other')),
  due_at timestamptz,
  sent_at timestamptz,
  channel text,
  receipt_reference text,
  receipt_document_id uuid,
  contains_identity boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','acknowledged','overdue','not_required')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_authority_communications_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_authority_communications_subject_type_subject_id_kind UNIQUE (tenant_id, subject_type, subject_id, kind),
  CONSTRAINT fk_authority_communications_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_authority_communications_receipt_document_id FOREIGN KEY (tenant_id, receipt_document_id) REFERENCES documents (tenant_id, id)
);
COMMENT ON TABLE authority_communications IS 'Comunicaciones obligatorias a la autoridad (MTPE, SUNAFIL) con su plazo, cargo de presentación y estado.';
CREATE INDEX ix_authority_communications_legal_entity_id ON authority_communications (tenant_id, legal_entity_id);
CREATE INDEX ix_authority_communications_receipt_document_id ON authority_communications (tenant_id, receipt_document_id);
ALTER TABLE authority_communications ENABLE ROW LEVEL SECURITY;
ALTER TABLE authority_communications FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON authority_communications USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_authority_communications_touch BEFORE UPDATE ON authority_communications FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE evidence_exports (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
