CREATE TABLE data_banks (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  legal_entity_id uuid NOT NULL,
  name text NOT NULL,
  registry_code text,
  purpose text,
  data_categories text[],
  contains_sensitive boolean NOT NULL DEFAULT false,
  hosting_country text,
  cross_border_transfer boolean NOT NULL DEFAULT false,
  security_measures text,
  registered_on date,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','registered','updated','cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
