  CONSTRAINT fk_unions_dues_concept_id FOREIGN KEY (tenant_id, dues_concept_id) REFERENCES payroll_concepts (tenant_id, id)
);
COMMENT ON TABLE unions IS 'Organización sindical y regla de cuota (E-17).';
