CREATE TABLE union_memberships (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  union_id uuid NOT NULL,
  employment_id uuid NOT NULL,
  is_representative boolean NOT NULL DEFAULT false,
  representative_role text,
  dues_authorized boolean NOT NULL DEFAULT false,
  authorization_document_id uuid,
  valid_from date NOT NULL,
  valid_to date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_union_memberships_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT ck_union_memberships_vigencia CHECK (valid_to IS NULL OR valid_to >= valid_from),
  CONSTRAINT ex_union_memberships_vigencia EXCLUDE USING gist (tenant_id WITH =, union_id WITH =, employment_id WITH =, daterange(valid_from, valid_to, '[]') WITH &&) WHERE (deleted_at IS NULL) DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_union_memberships_union_id FOREIGN KEY (tenant_id, union_id) REFERENCES unions (tenant_id, id),
  CONSTRAINT fk_union_memberships_employment_id FOREIGN KEY (tenant_id, employment_id) REFERENCES employments (tenant_id, id),
  CONSTRAINT fk_union_memberships_authorization_document_id FOREIGN KEY (tenant_id, authorization_document_id) REFERENCES documents (tenant_id, id)
);
COMMENT ON TABLE union_memberships IS 'Afiliación sindical con vigencia. Dato sensible: acceso por permiso de campo y registro de accesos. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE INDEX ix_union_memberships_employment_id ON union_memberships (tenant_id, employment_id);
