  data_scopes text[] NOT NULL,
  permissions_snapshot text[],
  referenced_entities jsonb,
  model text,
  provider text,
  input_tokens integer,
  output_tokens integer,
  was_blocked boolean NOT NULL DEFAULT false,
  block_reason text,
  high_impact_flag boolean NOT NULL DEFAULT false,
  api_token_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_ai_interactions_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_ai_interactions_user_id FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE ai_interactions IS 'Bitácora inalterable de cada uso de IA (C-08): quién, con qué permisos, qué datos consultó y qué respondió. -- SENSIBLE: acceso por permiso de campo y registrado en data_access_logs.';
CREATE INDEX ix_ai_interactions_user_id ON ai_interactions (tenant_id, user_id);
CREATE INDEX ix_ai_interactions_api_token_id ON ai_interactions (tenant_id, api_token_id);
ALTER TABLE ai_interactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_interactions FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ai_interactions USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_ai_interactions_inmutable BEFORE UPDATE OR DELETE ON ai_interactions FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER trg_ai_interactions_no_truncate BEFORE TRUNCATE ON ai_interactions FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

CREATE TABLE ai_use_case_settings (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  use_case text NOT NULL,
  is_enabled boolean NOT NULL DEFAULT false,
  question_limit integer,
  limit_period text NOT NULL DEFAULT 'day' CHECK (limit_period IN ('day','week','month')),
  notice text,
  changed_by_user_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_ai_use_case_settings_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_ai_use_case_settings_use_case UNIQUE (tenant_id, use_case),
  CONSTRAINT fk_ai_use_case_settings_changed_by_user_id FOREIGN KEY (tenant_id, changed_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE ai_use_case_settings IS 'Activación por caso de uso de IA, incluido el asistente de ayuda (`help_assistant`): encendido, límite de preguntas por usuario y aviso. Sin fila, el caso de uso está apagado (RN-IAR-05).';
CREATE INDEX ix_ai_use_case_settings_changed_by_user_id ON ai_use_case_settings (tenant_id, changed_by_user_id);
ALTER TABLE ai_use_case_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_use_case_settings FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ai_use_case_settings USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_ai_use_case_settings_touch BEFORE UPDATE ON ai_use_case_settings FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE ai_use_case_roles (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  ai_use_case_setting_id uuid NOT NULL,
  role_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_ai_use_case_roles_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_ai_use_case_roles_ai_use_case_setting_id_role_id UNIQUE (tenant_id, ai_use_case_setting_id, role_id),
  CONSTRAINT fk_ai_use_case_roles_ai_use_case_setting_id FOREIGN KEY (tenant_id, ai_use_case_setting_id) REFERENCES ai_use_case_settings (tenant_id, id),
  CONSTRAINT fk_ai_use_case_roles_role_id FOREIGN KEY (tenant_id, role_id) REFERENCES roles (tenant_id, id)
);
COMMENT ON TABLE ai_use_case_roles IS 'Roles habilitados para un caso de uso de IA; sin filas, ningún rol lo ve.';
CREATE INDEX ix_ai_use_case_roles_role_id ON ai_use_case_roles (tenant_id, role_id);
ALTER TABLE ai_use_case_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_use_case_roles FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ai_use_case_roles USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_ai_use_case_roles_touch BEFORE UPDATE ON ai_use_case_roles FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE ai_feedback (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  ai_interaction_id uuid NOT NULL,
  user_id uuid NOT NULL,
  rating text NOT NULL CHECK (rating IN ('up','down')),
  comment text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_ai_feedback_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_ai_feedback_ai_interaction_id_user_id UNIQUE (tenant_id, ai_interaction_id, user_id),
  CONSTRAINT fk_ai_feedback_ai_interaction_id FOREIGN KEY (tenant_id, ai_interaction_id) REFERENCES ai_interactions (tenant_id, id),
  CONSTRAINT fk_ai_feedback_user_id FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE ai_feedback IS 'Valoración del usuario sobre una respuesta de IA.';
CREATE INDEX ix_ai_feedback_user_id ON ai_feedback (tenant_id, user_id);
ALTER TABLE ai_feedback ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_feedback FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ai_feedback USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_ai_feedback_touch BEFORE UPDATE ON ai_feedback FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE ai_suggestions (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  ai_interaction_id uuid NOT NULL,
  subject_type text,
  subject_id uuid,
  kind text NOT NULL,
  content jsonb NOT NULL,
  status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','accepted','edited','rejected')),
  decided_by_user_id uuid,
  decided_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_ai_suggestions_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_ai_suggestions_ai_interaction_id FOREIGN KEY (tenant_id, ai_interaction_id) REFERENCES ai_interactions (tenant_id, id),
  CONSTRAINT fk_ai_suggestions_decided_by_user_id FOREIGN KEY (tenant_id, decided_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE ai_suggestions IS 'Borrador o sugerencia de IA que solo surte efecto si una persona lo acepta (regla 9).';
CREATE INDEX ix_ai_suggestions_ai_interaction_id ON ai_suggestions (tenant_id, ai_interaction_id);
CREATE INDEX ix_ai_suggestions_decided_by_user_id ON ai_suggestions (tenant_id, decided_by_user_id);
ALTER TABLE ai_suggestions ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_suggestions FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ai_suggestions USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_ai_suggestions_touch BEFORE UPDATE ON ai_suggestions FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

-- ==================================================================================================
-- FASE 9 · ECOSISTEMA Y EXPANSIÓN
-- ==================================================================================================

-- --------------------------------------------------------------------------------------------------
-- API · API pública, webhooks y MCP
-- --------------------------------------------------------------------------------------------------

CREATE TABLE api_tokens (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  name text NOT NULL,
  token_prefix text NOT NULL,
  token_hash text NOT NULL,
  owner_user_id uuid,
  scopes text[] NOT NULL,
  kind text NOT NULL DEFAULT 'service' CHECK (kind IN ('personal','service','mcp','partner')),
  ip_allowlist cidr[],
  expires_at timestamptz,
  last_used_at timestamptz,
  revoked_at timestamptz,
  rate_limit_per_minute integer,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_api_tokens_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_api_tokens_owner_user_id FOREIGN KEY (tenant_id, owner_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE api_tokens IS 'Token de API con alcances (scopes); solo se guarda su huella.';
CREATE UNIQUE INDEX uq_api_tokens_token_hash ON api_tokens (tenant_id, token_hash) WHERE deleted_at IS NULL;
CREATE INDEX ix_api_tokens_owner_user_id ON api_tokens (tenant_id, owner_user_id);
ALTER TABLE api_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_tokens FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON api_tokens USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_api_tokens_touch BEFORE UPDATE ON api_tokens FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE oauth_clients (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  name text NOT NULL,
  client_id text NOT NULL,
  client_secret_hash text,
  redirect_uris text[],
  scopes text[],
  kind text NOT NULL CHECK (kind IN ('mcp','integration','partner')),
  is_confidential boolean NOT NULL DEFAULT true,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_oauth_clients_tenant_id UNIQUE (tenant_id, id)
);
COMMENT ON TABLE oauth_clients IS 'Clientes autorizados (asistentes de IA por MCP, integraciones, socios).';
CREATE UNIQUE INDEX uq_oauth_clients_client_id ON oauth_clients (tenant_id, client_id) WHERE deleted_at IS NULL;
ALTER TABLE oauth_clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth_clients FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON oauth_clients USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_oauth_clients_touch BEFORE UPDATE ON oauth_clients FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE webhook_endpoints (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  name text NOT NULL,
  url text NOT NULL,
  secret_enc text NOT NULL,  -- SENSIBLE (cifrado en la aplicación)
  event_types text[] NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','disabled_by_failures')),
  api_version text,
  failure_count integer NOT NULL DEFAULT 0,
  last_success_at timestamptz,
  last_failure_at timestamptz,
  created_by_user_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_webhook_endpoints_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_webhook_endpoints_created_by_user_id FOREIGN KEY (tenant_id, created_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE webhook_endpoints IS 'Destino de webhooks con secreto de firma y tipos de evento suscritos.';
CREATE INDEX ix_webhook_endpoints_created_by_user_id ON webhook_endpoints (tenant_id, created_by_user_id);
ALTER TABLE webhook_endpoints ENABLE ROW LEVEL SECURITY;
ALTER TABLE webhook_endpoints FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON webhook_endpoints USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_webhook_endpoints_touch BEFORE UPDATE ON webhook_endpoints FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE webhook_deliveries (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  webhook_endpoint_id uuid NOT NULL,
  outbox_event_id uuid,
  event_type text NOT NULL,
  payload jsonb NOT NULL,
  attempt integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','delivered','failed','dead')),
  response_status integer,
  response_body text,
  duration_ms integer,
  next_attempt_at timestamptz,
  delivered_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_webhook_deliveries_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_webhook_deliveries_webhook_endpoint_id FOREIGN KEY (tenant_id, webhook_endpoint_id) REFERENCES webhook_endpoints (tenant_id, id),
  CONSTRAINT fk_webhook_deliveries_outbox_event_id FOREIGN KEY (tenant_id, outbox_event_id) REFERENCES outbox_events (tenant_id, id)
);
COMMENT ON TABLE webhook_deliveries IS 'Entregas de webhooks con reintentos (salen del outbox).';
CREATE INDEX ix_webhook_deliveries_webhook_endpoint_id ON webhook_deliveries (tenant_id, webhook_endpoint_id);
CREATE INDEX ix_webhook_deliveries_outbox_event_id ON webhook_deliveries (tenant_id, outbox_event_id);
CREATE INDEX ix_webhook_deliveries_status_next_attempt_at ON webhook_deliveries (tenant_id, status, next_attempt_at);
ALTER TABLE webhook_deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE webhook_deliveries FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON webhook_deliveries USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_webhook_deliveries_touch BEFORE UPDATE ON webhook_deliveries FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE api_request_logs (
  id uuid NOT NULL DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  api_token_id uuid,
  oauth_client_id uuid,
  method text NOT NULL,
  path text NOT NULL,
  status_code integer NOT NULL,
  duration_ms integer,
  ip inet,
  request_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pk_api_request_logs PRIMARY KEY (id, occurred_at),
  CONSTRAINT uq_api_request_logs_tenant_id UNIQUE (tenant_id, id, occurred_at),
  CONSTRAINT fk_api_request_logs_api_token_id FOREIGN KEY (tenant_id, api_token_id) REFERENCES api_tokens (tenant_id, id),
  CONSTRAINT fk_api_request_logs_oauth_client_id FOREIGN KEY (tenant_id, oauth_client_id) REFERENCES oauth_clients (tenant_id, id)
) PARTITION BY RANGE (occurred_at);
COMMENT ON TABLE api_request_logs IS 'Uso de la API por token o cliente (medición y límites); no es el log técnico.';
CREATE INDEX ix_api_request_logs_api_token_id ON api_request_logs (tenant_id, api_token_id);
CREATE INDEX ix_api_request_logs_oauth_client_id ON api_request_logs (tenant_id, oauth_client_id);
CREATE INDEX ix_api_request_logs_occurred_at ON api_request_logs (tenant_id, occurred_at);
CREATE TABLE api_request_logs_default PARTITION OF api_request_logs DEFAULT;
COMMENT ON TABLE api_request_logs_default IS 'Partición de respaldo de api_request_logs: no debería recibir filas; si las recibe, falta crear el mes con ensure_monthly_partitions().';
ALTER TABLE api_request_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_request_logs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON api_request_logs USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE api_request_logs_default ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_request_logs_default FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON api_request_logs_default USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

-- --------------------------------------------------------------------------------------------------
-- INT · Integraciones
-- --------------------------------------------------------------------------------------------------

CREATE TABLE integration_connectors (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  code text NOT NULL,
  name text NOT NULL,
  category text NOT NULL CHECK (category IN ('erp','accounting','bank','biometric','email','calendar','sso','signature','ats','lms','messaging','wallet','storage','other')),
  has_fake_adapter boolean NOT NULL DEFAULT true,
  config_schema jsonb,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_integration_connectors_code UNIQUE (code)
);
COMMENT ON TABLE integration_connectors IS 'Catálogo de conectores (ERP, contabilidad, bancos, biométricos, correo, calendario, SSO, firma, mensajería, billeteras), todos con adaptador falso.';
CREATE TRIGGER trg_integration_connectors_touch BEFORE UPDATE ON integration_connectors FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE integrations (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
