  name text NOT NULL,
  legal_entity_id uuid,
  config jsonb,
  credentials_enc text,  -- SENSIBLE (cifrado en la aplicación)
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','error','paused')),
  use_fake_adapter boolean NOT NULL DEFAULT false,
  last_sync_at timestamptz,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_integrations_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_integrations_connector_code FOREIGN KEY (connector_code) REFERENCES integration_connectors (code),
  CONSTRAINT fk_integrations_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id)
);
COMMENT ON TABLE integrations IS 'Integración configurada por la organización; credenciales cifradas.';
CREATE INDEX ix_integrations_connector_code ON integrations (tenant_id, connector_code);
CREATE INDEX ix_integrations_legal_entity_id ON integrations (tenant_id, legal_entity_id);
ALTER TABLE integrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE integrations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON integrations USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_integrations_touch BEFORE UPDATE ON integrations FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE integration_sync_runs (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
