);
COMMENT ON TABLE integration_sync_runs IS 'Ejecuciones de sincronización.';
CREATE INDEX ix_integration_sync_runs_integration_id ON integration_sync_runs (tenant_id, integration_id);
ALTER TABLE integration_sync_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE integration_sync_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON integration_sync_runs USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE TABLE integration_mappings (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
