  CONSTRAINT uq_integration_mappings_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_integration_mappings_integration_id_entity_type_entity_id UNIQUE (tenant_id, integration_id, entity_type, entity_id),
