COMMENT ON TABLE integration_mappings IS 'Correspondencia entre registros propios e identificadores externos.';
CREATE INDEX ix_integration_mappings_integration_id_entity_type_external_id ON integration_mappings (tenant_id, integration_id, entity_type, external_id);
ALTER TABLE integration_mappings ENABLE ROW LEVEL SECURITY;
ALTER TABLE integration_mappings FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON integration_mappings USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_integration_mappings_touch BEFORE UPDATE ON integration_mappings FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE sso_connections (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
