-- --------------------------------------------------------------------------------------------------
-- WHA · Autoservicio por WhatsApp
-- --------------------------------------------------------------------------------------------------

CREATE TABLE whatsapp_contacts (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  person_id uuid,
  user_id uuid,
  phone_hash text NOT NULL,
  phone_enc text NOT NULL,  -- SENSIBLE (cifrado en la aplicación)
  opted_in_at timestamptz,
  opted_out_at timestamptz,
  verified_at timestamptz,
  consent_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_whatsapp_contacts_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT uq_whatsapp_contacts_phone_hash UNIQUE (tenant_id, phone_hash),
  CONSTRAINT fk_whatsapp_contacts_person_id FOREIGN KEY (tenant_id, person_id) REFERENCES people (tenant_id, id),
  CONSTRAINT fk_whatsapp_contacts_user_id FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_whatsapp_contacts_consent_id FOREIGN KEY (tenant_id, consent_id) REFERENCES consents (tenant_id, id)
);
COMMENT ON TABLE whatsapp_contacts IS 'Número de WhatsApp verificado de una persona, con consentimiento (E-11).';
CREATE INDEX ix_whatsapp_contacts_person_id ON whatsapp_contacts (tenant_id, person_id);
CREATE INDEX ix_whatsapp_contacts_user_id ON whatsapp_contacts (tenant_id, user_id);
CREATE INDEX ix_whatsapp_contacts_consent_id ON whatsapp_contacts (tenant_id, consent_id);
ALTER TABLE whatsapp_contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE whatsapp_contacts FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON whatsapp_contacts USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_whatsapp_contacts_touch BEFORE UPDATE ON whatsapp_contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_lock();

CREATE TABLE whatsapp_conversations (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  whatsapp_contact_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')),
  intent text,
  last_message_at timestamptz,
  session_expires_at timestamptz,
  ticket_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_whatsapp_conversations_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_whatsapp_conversations_whatsapp_contact_id FOREIGN KEY (tenant_id, whatsapp_contact_id) REFERENCES whatsapp_contacts (tenant_id, id),
  CONSTRAINT fk_whatsapp_conversations_ticket_id FOREIGN KEY (tenant_id, ticket_id) REFERENCES tickets (tenant_id, id)
);
COMMENT ON TABLE whatsapp_conversations IS 'Conversación de autoservicio.';
CREATE INDEX ix_whatsapp_conversations_whatsapp_contact_id ON whatsapp_conversations (tenant_id, whatsapp_contact_id);
CREATE INDEX ix_whatsapp_conversations_ticket_id ON whatsapp_conversations (tenant_id, ticket_id);
ALTER TABLE whatsapp_conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE whatsapp_conversations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON whatsapp_conversations USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_whatsapp_conversations_touch BEFORE UPDATE ON whatsapp_conversations FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE whatsapp_messages (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  whatsapp_conversation_id uuid NOT NULL,
  direction text NOT NULL CHECK (direction IN ('inbound','outbound')),
  kind text NOT NULL CHECK (kind IN ('text','template','document','image','location','interactive')),
  body_enc text,  -- SENSIBLE (cifrado en la aplicación)
  template_code text,
  stored_file_id uuid,
  provider_message_id text,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sent','delivered','read','failed')),
  action_type text,
  action_ref uuid,
  error text,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_whatsapp_messages_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_whatsapp_messages_whatsapp_conversation_id FOREIGN KEY (tenant_id, whatsapp_conversation_id) REFERENCES whatsapp_conversations (tenant_id, id),
  CONSTRAINT fk_whatsapp_messages_stored_file_id FOREIGN KEY (tenant_id, stored_file_id) REFERENCES stored_files (tenant_id, id)
);
COMMENT ON TABLE whatsapp_messages IS 'Mensajes entrantes y salientes y la acción que ejecutaron (boleta, vacaciones, constancia, marcación).';
CREATE INDEX ix_whatsapp_messages_whatsapp_conversation_id ON whatsapp_messages (tenant_id, whatsapp_conversation_id);
CREATE INDEX ix_whatsapp_messages_stored_file_id ON whatsapp_messages (tenant_id, stored_file_id);
ALTER TABLE whatsapp_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE whatsapp_messages FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON whatsapp_messages USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE TABLE whatsapp_templates (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  code text NOT NULL,
  locale text NOT NULL DEFAULT 'es',
  category text,
  body text NOT NULL,
  provider_status text NOT NULL DEFAULT 'draft' CHECK (provider_status IN ('draft','submitted','approved','rejected')),
  variables jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CONSTRAINT uq_whatsapp_templates_tenant_id UNIQUE (tenant_id, id)
);
COMMENT ON TABLE whatsapp_templates IS 'Plantillas de mensaje aprobadas por el proveedor.';
CREATE UNIQUE INDEX uq_whatsapp_templates_code_locale ON whatsapp_templates (tenant_id, code, locale) WHERE deleted_at IS NULL;
ALTER TABLE whatsapp_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE whatsapp_templates FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON whatsapp_templates USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
CREATE TRIGGER trg_whatsapp_templates_touch BEFORE UPDATE ON whatsapp_templates FOR EACH ROW EXECUTE FUNCTION set_updated_at();

