CREATE TRIGGER trg_country_concept_templates_touch BEFORE UPDATE ON country_concept_templates FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE country_document_templates (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
