CREATE TABLE partner_firms (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  name text NOT NULL,
  tax_id text,
  country_code text,
  contact_email text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
COMMENT ON TABLE partner_firms IS 'Estudio contable o socio que administra las planillas de varias organizaciones (E-24).';
CREATE TRIGGER trg_partner_firms_touch BEFORE UPDATE ON partner_firms FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE partner_firm_users (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  partner_firm_id uuid NOT NULL,
  email text NOT NULL,
  full_name text,
  password_hash text,  -- SENSIBLE
  role text NOT NULL DEFAULT 'accountant' CHECK (role IN ('owner','accountant','assistant')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_partner_firm_users_email UNIQUE (email),
  CONSTRAINT fk_partner_firm_users_partner_firm_id FOREIGN KEY (partner_firm_id) REFERENCES partner_firms (id)
);
COMMENT ON TABLE partner_firm_users IS 'Usuarios del estudio en la consola de socio.';
CREATE INDEX ix_partner_firm_users_partner_firm_id ON partner_firm_users (partner_firm_id);
CREATE TRIGGER trg_partner_firm_users_touch BEFORE UPDATE ON partner_firm_users FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE partner_firm_tenants (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  partner_firm_id uuid NOT NULL,
  tenant_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited','active','revoked')),
  since date,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_partner_firm_tenants_partner_firm_id_tenant_id UNIQUE (partner_firm_id, tenant_id),
  CONSTRAINT fk_partner_firm_tenants_partner_firm_id FOREIGN KEY (partner_firm_id) REFERENCES partner_firms (id),
  CONSTRAINT fk_partner_firm_tenants_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id)
);
COMMENT ON TABLE partner_firm_tenants IS 'Organizaciones que administra un estudio.';
CREATE INDEX ix_partner_firm_tenants_tenant_id ON partner_firm_tenants (tenant_id);
CREATE TRIGGER trg_partner_firm_tenants_touch BEFORE UPDATE ON partner_firm_tenants FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE partner_access_grants (
  id uuid PRIMARY KEY DEFAULT uuid_v7(),
  tenant_id uuid NOT NULL REFERENCES tenants (id),
  partner_firm_id uuid NOT NULL,
  partner_firm_user_id uuid,
  role_id uuid NOT NULL,
  legal_entity_id uuid,
  user_id uuid,
  granted_by_user_id uuid NOT NULL,
  granted_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  lock_version integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_partner_access_grants_tenant_id UNIQUE (tenant_id, id),
  CONSTRAINT fk_partner_access_grants_partner_firm_id FOREIGN KEY (partner_firm_id) REFERENCES partner_firms (id),
  CONSTRAINT fk_partner_access_grants_partner_firm_user_id FOREIGN KEY (partner_firm_user_id) REFERENCES partner_firm_users (id),
  CONSTRAINT fk_partner_access_grants_role_id FOREIGN KEY (tenant_id, role_id) REFERENCES roles (tenant_id, id),
  CONSTRAINT fk_partner_access_grants_legal_entity_id FOREIGN KEY (tenant_id, legal_entity_id) REFERENCES legal_entities (tenant_id, id),
  CONSTRAINT fk_partner_access_grants_user_id FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id),
  CONSTRAINT fk_partner_access_grants_granted_by_user_id FOREIGN KEY (tenant_id, granted_by_user_id) REFERENCES users (tenant_id, id)
);
COMMENT ON TABLE partner_access_grants IS 'Autorización de la organización a un estudio: con qué rol y sobre qué empresa actúa.';
CREATE INDEX ix_partner_access_grants_partner_firm_id ON partner_access_grants (tenant_id, partner_firm_id);
CREATE INDEX ix_partner_access_grants_partner_firm_user_id ON partner_access_grants (tenant_id, partner_firm_user_id);
CREATE INDEX ix_partner_access_grants_role_id ON partner_access_grants (tenant_id, role_id);
CREATE INDEX ix_partner_access_grants_legal_entity_id ON partner_access_grants (tenant_id, legal_entity_id);
CREATE INDEX ix_partner_access_grants_user_id ON partner_access_grants (tenant_id, user_id);
CREATE INDEX ix_partner_access_grants_granted_by_user_id ON partner_access_grants (tenant_id, granted_by_user_id);
ALTER TABLE partner_access_grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE partner_access_grants FORCE ROW LEVEL SECURITY;
