INSERT INTO system_roles (code, name, description, realm, mfa_required_default) VALUES
  ('superadmin_saas', 'Superadmin SaaS', 'Propietario del SaaS. Opera en una consola aparte; no es un rol de organización y no ve datos de RRHH salvo acceso de soporte autorizado.', 'platform', true),
  ('admin_empresa', 'Administrador empresa', 'Administra la organización completa. Por defecto no accede a denuncias ni a datos médicos: esos permisos se asignan aparte.', 'tenant', true),
  ('rrhh', 'RRHH', 'Gestión de personas en toda la organización. No procesa ni cierra planilla y no ve diagnósticos médicos ni denuncias.', 'tenant', false),
  ('payroll', 'Payroll', 'Responsable de planilla: conceptos, periodos, cálculo, boletas, beneficios sociales, declaraciones, préstamos y locadores.', 'tenant', true),
  ('recruiter', 'Recruiter', 'Reclutamiento y selección. No ve sueldos de colaboradores.', 'tenant', false),
  ('manager', 'Manager', 'Jefe de equipo: ve y aprueba lo de quienes le reportan. Por defecto no ve sueldos (C-10). Se combina con el rol Empleado.', 'tenant', false),
  ('empleado', 'Empleado', 'Autoservicio: cada colaborador ve y gestiona solo lo propio. Sirve para personal sin correo corporativo (C-09).', 'tenant', false),
  ('auditor', 'Auditor', 'Solo lectura sobre la organización, incluida la auditoría.', 'tenant', false),
  ('sst', 'SST', 'Seguridad y salud en el trabajo, equipos de protección y capacitación obligatoria.', 'tenant', false),
  ('investigador_denuncias', 'Investigador de denuncias', 'Acceso restringido al canal de denuncias: solo los casos que tiene asignados (complaint_assignments).', 'tenant', true),
  ('contador', 'Contador', 'Solo lectura de planilla y asientos; puede exportar asientos contables.', 'tenant', false);
