INSERT INTO parameter_definitions (code, module_code, name, description, data_type, default_value, allowed_scopes, options) VALUES
  ('org.idioma_defecto', 'base', 'Idioma por defecto', 'Idioma de la interfaz y de los documentos.', 'select', '"es"'::jsonb, ARRAY['organization','legal_entity'], '["es", "en", "pt"]'::jsonb),
  ('org.zona_horaria', 'base', 'Zona horaria', 'Zona horaria para fechas, marcaciones y vencimientos.', 'text', '"America/Lima"'::jsonb, ARRAY['organization','legal_entity','site'], NULL),
  ('org.moneda_defecto', 'base', 'Moneda por defecto', 'Moneda ISO 4217 de los montos nuevos.', 'text', '"PEN"'::jsonb, ARRAY['organization','legal_entity'], NULL),
  ('org.inicio_semana', 'base', 'Primer día de la semana', 'Día en que empieza la semana en calendarios.', 'select', '"lunes"'::jsonb, ARRAY['organization'], '["lunes", "domingo"]'::jsonb),
  ('seguridad.acceso_con_documento', 'base', 'Acceso con documento de identidad', 'Permite ingresar con documento y clave u OTP, sin correo (C-09).', 'boolean', 'true'::jsonb, ARRAY['organization'], NULL),
  ('seguridad.canal_otp', 'base', 'Canal de clave temporal', 'Canal para enviar la clave temporal.', 'select', '"sms"'::jsonb, ARRAY['organization'], '["sms", "whatsapp", "email"]'::jsonb),
  ('seguridad.clave_longitud_minima', 'base', 'Longitud mínima de la clave', 'Cantidad mínima de caracteres de una clave nueva.', 'integer', '12'::jsonb, ARRAY['organization'], '{"min": 10, "max": 64}'::jsonb),
  ('seguridad.clave_historial', 'base', 'Claves anteriores que no se pueden repetir', 'Cuántas claves anteriores se recuerdan para impedir reutilizarlas. 0: no se controla.', 'integer', '5'::jsonb, ARRAY['organization'], '{"min": 0, "max": 24}'::jsonb),
  ('seguridad.clave_vencimiento_dias', 'base', 'Vencimiento de la clave (días)', 'Días tras los cuales se pide cambiar la clave. 0: no vence.', 'integer', '0'::jsonb, ARRAY['organization'], '{"min": 0, "max": 365}'::jsonb),
  ('seguridad.intentos_maximos', 'base', 'Intentos fallidos antes del bloqueo', 'Ingresos fallidos seguidos que bloquean la cuenta temporalmente.', 'integer', '5'::jsonb, ARRAY['organization'], '{"min": 3, "max": 10}'::jsonb),
  ('seguridad.bloqueo_minutos', 'base', 'Duración del bloqueo (minutos)', 'Tiempo que la cuenta queda bloqueada tras superar los intentos.', 'integer', '15'::jsonb, ARRAY['organization'], '{"min": 5, "max": 1440}'::jsonb),
  ('seguridad.sesion_duracion_minutos', 'base', 'Duración máxima de la sesión (minutos)', 'Tiempo tras el cual hay que volver a ingresar aunque se esté usando.', 'integer', '480'::jsonb, ARRAY['organization'], '{"min": 30, "max": 1440}'::jsonb),
  ('seguridad.inactividad_minutos', 'base', 'Cierre por inactividad (minutos)', 'Minutos sin uso tras los cuales la sesión se cierra.', 'integer', '30'::jsonb, ARRAY['organization'], '{"min": 5, "max": 240}'::jsonb),
  ('seguridad.mfa_todos', 'base', 'Verificación en dos pasos para todos', 'Exige el segundo factor a todos los usuarios, además de los roles que ya lo exigen.', 'boolean', 'false'::jsonb, ARRAY['organization'], NULL),
  ('seguridad.otp_minutos', 'base', 'Vigencia del código por mensaje (minutos)', 'Minutos que dura el código de ingreso o de activación enviado por SMS o WhatsApp.', 'integer', '5'::jsonb, ARRAY['organization'], '{"min": 2, "max": 15}'::jsonb),
  ('seguridad.otp_intentos', 'base', 'Intentos por código', 'Intentos fallidos que admite un código antes de anularse.', 'integer', '5'::jsonb, ARRAY['organization'], '{"min": 3, "max": 10}'::jsonb),
  ('seguridad.otp_reenvio_segundos', 'base', 'Espera para pedir otro código (segundos)', 'Tiempo mínimo entre dos envíos de código al mismo usuario.', 'integer', '60'::jsonb, ARRAY['organization'], '{"min": 30, "max": 600}'::jsonb),
  ('seguridad.marca_agua_descargas', 'base', 'Marca de agua en exportaciones', 'Agrega a cada archivo exportado el nombre de quien lo descargó y la fecha.', 'boolean', 'false'::jsonb, ARRAY['organization'], NULL),
  ('seguridad.registrar_acceso_sensible', 'base', 'Registrar accesos a datos sensibles', 'Deja constancia de cada consulta de sueldo, salud, denuncias, sanciones o biometría.', 'boolean', 'true'::jsonb, ARRAY['organization'], NULL),
  ('importacion.politica_errores', 'core', 'Filas con error al importar', 'Si una importación tiene filas con error: importar solo las válidas (las demás se descargan con su motivo) o exigir que se corrija todo antes (RN-IMP-02).', 'select', '"only_valid"'::jsonb, ARRAY['organization'], '["only_valid", "fix_all"]'::jsonb),
  ('importacion.tamano_lote', 'core', 'Filas por lote de importación', 'Filas que se confirman juntas en una transacción; si un lote falla, se deshace la importación completa.', 'integer', '500'::jsonb, ARRAY['organization'], '{"min": 50, "max": 5000}'::jsonb),
  ('importacion.max_filas', 'core', 'Filas máximas por archivo', 'Filas que admite un archivo de importación; los archivos más grandes se dividen.', 'integer', '50000'::jsonb, ARRAY['organization'], '{"min": 100, "max": 200000}'::jsonb),
  ('papelera.dias_restauracion', 'base', 'Días en papelera', 'Días durante los que un registro eliminado puede restaurarse desde la papelera.', 'integer', '30'::jsonb, ARRAY['organization'], NULL),
  ('aprobaciones.recordatorio_horas', 'base', 'Recordatorio de aprobación', 'Horas tras las que se recuerda una aprobación pendiente.', 'integer', '24'::jsonb, ARRAY['organization'], NULL),
  ('aprobaciones.escalar_horas', 'base', 'Escalamiento de aprobación', 'Horas tras las que una aprobación pendiente sube al siguiente nivel.', 'integer', '72'::jsonb, ARRAY['organization'], NULL),
  ('aprobaciones.permitir_masivas', 'base', 'Aprobaciones masivas', 'Permite aprobar varias solicitudes a la vez cuando el tipo lo admite.', 'boolean', 'true'::jsonb, ARRAY['organization'], NULL),
  ('automatizaciones.max_ejecuciones_hora', 'base', 'Ejecuciones por hora de una regla', 'Ejecuciones de una misma regla en una hora a partir de las cuales se pausa sola y se avisa al administrador (protección contra bucles, RN-WFL-11).', 'integer', '100'::jsonb, ARRAY['organization'], '{"min": 10, "max": 10000}'::jsonb),
  ('automatizaciones.reintentos', 'base', 'Reintentos de una acción fallida', 'Veces que se reintenta automáticamente una ejecución fallida antes de dejarla para revisión manual (RN-WFL-10).', 'integer', '3'::jsonb, ARRAY['organization'], '{"min": 0, "max": 10}'::jsonb),
  ('notificaciones.canales_activos', 'base', 'Canales de notificación', 'Canales habilitados para la organización.', 'list', '["in_app", "email"]'::jsonb, ARRAY['organization'], '["in_app", "email", "push", "whatsapp", "sms"]'::jsonb),
  ('notificaciones.silencio_desde', 'base', 'Inicio del horario de silencio', 'Hora local desde la que los avisos no urgentes por correo se envían al terminar el silencio. Vacío: sin silencio.', 'time', 'null'::jsonb, ARRAY['organization'], NULL),
  ('notificaciones.silencio_hasta', 'base', 'Fin del horario de silencio', 'Hora local en que se entregan los avisos que esperaron por el silencio.', 'time', 'null'::jsonb, ARRAY['organization'], NULL),
  ('notificaciones.obligatorias', 'base', 'Avisos obligatorios', 'Tipos de aviso que el usuario no puede desactivar en la aplicación, además de los del producto.', 'list', '[]'::jsonb, ARRAY['organization'], '["approval.pending", "approval.reminder", "approval.escalated", "approval.approved", "approval.rejected", "task.assigned", "task.overdue"]'::jsonb),
  ('notificaciones.retencion_dias', 'base', 'Retención de avisos leídos (días)', 'Días que un aviso leído se muestra en el centro de notificaciones antes de archivarse.', 'integer', '180'::jsonb, ARRAY['organization'], NULL),
  ('colaboradores.codigo_automatico', 'core', 'Código de colaborador automático', 'Genera el código con el correlativo de la empresa.', 'boolean', 'true'::jsonb, ARRAY['organization','legal_entity'], NULL),
